-- relationships kept in app.folder_teams
CREATE FUNCTION authz_int."rel_audit_1_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'folder' AS ot, x."folder_id"::text AS oid, 'team' AS rel, 'team' AS st, x."team_id"::text AS sid, 'member' AS sr FROM new_rows x WHERE true) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'folder' AS ot, x."folder_id"::text AS oid, 'team' AS rel, 'team' AS st, x."team_id"::text AS sid, 'member' AS sr FROM new_rows x WHERE true) c GROUP BY c.ot;
  RETURN NULL;
END $f$;
