-- one audit row per changed relationship column (a row trigger, so it also works when the key changes)
CREATE FUNCTION authz_int."folder__col_audit_row"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NEW."parent_id" IS DISTINCT FROM OLD."parent_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'folder', NEW."id"::text, 'parent', NEW."parent_id"::text, jsonb_build_object('column', 'parent_id', 'was', OLD."parent_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."owner_id" IS DISTINCT FROM OLD."owner_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'folder', NEW."id"::text, 'owner', NEW."owner_id"::text, jsonb_build_object('column', 'owner_id', 'was', OLD."owner_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  RETURN NULL;
END $f$;
-- @object trigger "authz_folder_col_audit_row" ON "app"."folders"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."folders"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_folder_col_audit_row" AFTER UPDATE ON "app"."folders" FOR EACH ROW WHEN (OLD."parent_id" IS DISTINCT FROM NEW."parent_id" OR OLD."owner_id" IS DISTINCT FROM NEW."owner_id") EXECUTE FUNCTION authz_int."folder__col_audit_row"()';
  ELSE
    RAISE NOTICE '% is not a table: changes to it are not audited or fed (audit)', '"app"."folders"';
  END IF;
END $tr$;

