        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = n."id"::text AND a.relation = 'folder' AND a.detail->>'column' = 'folder_id'
