DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."notes"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_note_col_audit_ins" AFTER INSERT ON "app"."notes" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."note__col_audit_ins"()';
  ELSE
