  END IF;
END $tr$;
CREATE FUNCTION authz_int."note__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('note', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."author_id" IS DISTINCT FROM o."author_id" OR n."file_id" IS DISTINCT FROM o."file_id"), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'note', n."id"::text, 'file', n."file_id"::text, jsonb_build_object('column', 'file_id', 'was', o."file_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."file_id" IS DISTINCT FROM o."file_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'note'
          AND a.object_id = n."id"::text AND a.relation = 'file' AND a.detail->>'column' = 'file_id'
          AND a.subject_id IS NOT DISTINCT FROM n."file_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."file_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'note', n."id"::text, 'author', n."author_id"::text, jsonb_build_object('column', 'author_id', 'was', o."author_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."author_id" IS DISTINCT FROM o."author_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'note'
          AND a.object_id = n."id"::text AND a.relation = 'author' AND a.detail->>'column' = 'author_id'
          AND a.subject_id IS NOT DISTINCT FROM n."author_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."author_id"));
    END IF;
  RETURN NULL;
END $f$;
-- @object trigger "authz_note_col_audit_upd" ON "app"."notes"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."notes"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_note_col_audit_upd" AFTER UPDATE ON "app"."notes" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."note__col_audit_upd"()';
