DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."notes"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_note_col_audit_row" AFTER UPDATE ON "app"."notes" FOR EACH ROW WHEN (OLD."file_id" IS DISTINCT FROM NEW."file_id" OR OLD."author_id" IS DISTINCT FROM NEW."author_id") EXECUTE FUNCTION authz_int."note__col_audit_row"()';
