-- folder.viewer (line 20)
CREATE VIEW authz_int."folder__viewer" AS
  SELECT g.object_id::integer AS id FROM authz.shares g WHERE g.object_type = 'folder' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL;

-- folder.view: where inheritance starts, for the current user
CREATE FUNCTION authz_int."folder__view__start"() RETURNS SETOF integer
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT ROWS 100 AS $f$
BEGIN
  RETURN QUERY
  (SELECT id FROM authz_int."folder__owner")
  UNION ALL
  (SELECT id FROM authz_int."folder__team")
  UNION ALL
  (SELECT id FROM authz_int."folder__viewer");
END $f$;

-- folder.view (line 23): edit or team or viewer or parent.view
CREATE VIEW authz_int."folder__view" AS
  SELECT c.descendant AS id FROM authz_int."folder__parent__tree" c
  WHERE c.ancestor IN (SELECT s.id FROM authz_int."folder__view__start"() s(id));

-- folder.view for one object (checks of single rows and authz.can)
CREATE FUNCTION authz_int."folder__view__has"(p_id integer) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" c
    WHERE c.descendant = p_id
      AND EXISTS (SELECT 1 FROM (
  (SELECT id FROM authz_int."folder__owner")
  UNION ALL
  (SELECT id FROM authz_int."folder__team")
  UNION ALL
  (SELECT id FROM authz_int."folder__viewer")) s WHERE s.id = c.ancestor));
END $f$;

