-- checked on the row after the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update_after parent_id" BEFORE UPDATE ON "app"."folders" FOR EACH ROW
  WHEN ((OLD."parent_id" IS DISTINCT FROM NEW."parent_id")
    AND pg_catalog.row_security_active('"app"."folders"'::pg_catalog.regclass)
    AND NOT authz_int."app.folders:column parent_id after:holds"(pg_catalog.jsonb_populate_record(NULL::"app"."folders", pg_catalog.to_jsonb(NEW))))
  EXECUTE FUNCTION authz_int."app.folders:column parent_id after"();

CREATE FUNCTION authz_gen."app.files:column owner_id:items"(p_row "app"."files") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."app.files:seen"("files"."id") THEN ARRAY[
    coalesce(coalesce((false), false), false),
    coalesce((SELECT authz_int.scope_cmd('app.files', 'update')), false),
    coalesce(true, false),
    coalesce(coalesce((false), false), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[4]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "files";
END;

CREATE FUNCTION authz_gen."app.files:column owner_id:why"(p_row "app"."files") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.files:column owner_id:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update owner_id : nobody  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.files update owner_id'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on app.files'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'nobody';
END $f$;

-- app.files update owner_id (line 49): nobody
-- Whether the rule holds for a row: called by the trigger's WHEN, which is kept parsed, as a policy is, so the app
-- role uses it without naming it (authz_int)
CREATE FUNCTION authz_int."app.files:column owner_id:holds"(p_row "app"."files") RETURNS boolean
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT coalesce(coalesce((false), false), false) FROM pg_catalog.unnest(ARRAY[p_row]) AS "files";
END;
-- refused: says why. The rule is checked in the trigger's WHEN below
CREATE FUNCTION authz_int."app.files:column owner_id"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "app"."files";
BEGIN
  -- the row as the table's own: a partition's columns may be in another order, a table that inherits may have more
  IF TG_RELID = '"app"."files"'::pg_catalog.regclass THEN v_row := OLD;
  ELSE v_row := pg_catalog.jsonb_populate_record(NULL::"app"."files", pg_catalog.to_jsonb(OLD)); END IF;
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.files:column owner_id:why"(v_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION 'changing owner_id of app.files % needs: nobody', OLD."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
    SCHEMA = 'app', TABLE = 'files', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
END $f$;
-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update owner_id" BEFORE UPDATE ON "app"."files" FOR EACH ROW
  WHEN ((OLD."owner_id" IS DISTINCT FROM NEW."owner_id")
    AND pg_catalog.row_security_active('"app"."files"'::pg_catalog.regclass)
    AND NOT authz_int."app.files:column owner_id:holds"(pg_catalog.jsonb_populate_record(NULL::"app"."files", pg_catalog.to_jsonb(OLD))))
  EXECUTE FUNCTION authz_int."app.files:column owner_id"();

-- Foreign keys that delete or change governed rows skip row-level security, unless a `cascade from` line
-- says they do as meant. ON UPDATE CASCADE is left out: it changes a row's reference to follow the key it names,
-- so the row still names the same row.
DO $fk$
DECLARE c record;
BEGIN
  FOR c IN SELECT con.conname, con.conrelid::regclass AS child,
                  concat_ws(' ', CASE con.confdeltype WHEN 'c' THEN 'ON DELETE CASCADE' WHEN 'n' THEN 'ON DELETE SET NULL'
                                                      WHEN 'd' THEN 'ON DELETE SET DEFAULT' END,
                                 CASE con.confupdtype WHEN 'n' THEN 'ON UPDATE SET NULL' WHEN 'd' THEN 'ON UPDATE SET DEFAULT' END) AS actions,
                  concat_ws(', and ',
                    CASE WHEN con.confdeltype IN ('c', 'n', 'd') THEN format('deleting a row of %s also %s rows of %s', con.confrelid::regclass,
                      CASE con.confdeltype WHEN 'c' THEN 'deletes' ELSE 'changes' END, con.conrelid::regclass) END,
                    CASE WHEN con.confupdtype IN ('n', 'd') THEN format('changing the key of a row of %s also changes rows of %s', con.confrelid::regclass, con.conrelid::regclass) END) AS effects,
                  CASE WHEN con.confdeltype <> 'c' THEN 'change' WHEN con.confupdtype IN ('n', 'd') THEN 'delete or change' ELSE 'delete' END AS verb,
                  -- the line that says it is meant, with the tables as a policy writes them (and the key's columns
                  -- where another key of the table to the same one acts too)
                  (SELECT n.nspname || '.' || r.relname FROM pg_class r JOIN pg_namespace n ON n.oid = r.relnamespace WHERE r.oid = con.conrelid) AS rules,
                  'cascade from ' || (SELECT n.nspname || '.' || r.relname FROM pg_class r JOIN pg_namespace n ON n.oid = r.relnamespace WHERE r.oid = con.confrelid)
                    || CASE WHEN EXISTS (SELECT 1 FROM pg_constraint o WHERE o.contype = 'f' AND o.conrelid = con.conrelid AND o.confrelid = con.confrelid
                                           AND o.oid <> con.oid AND (o.confdeltype IN ('c', 'n', 'd') OR o.confupdtype IN ('n', 'd')))
                       THEN ' (' || (SELECT string_agg(a.attname, ', ' ORDER BY k.n) FROM unnest(con.conkey) WITH ORDINALITY k(attnum, n)
                                     JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum) || ')' ELSE '' END AS line
           FROM pg_constraint con
           WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd'))
             AND con.conrelid IN ('"app"."folders"'::regclass, '"app"."files"'::regclass, '"app"."notes"'::regclass) LOOP
    RAISE WARNING 'foreign key % on % is %: %. Foreign key actions skip row-level security, so a user could % rows the policy doesn''t let them %. Use RESTRICT, or if that is meant, say so under rules %: %',
      c.conname, c.child, c.actions, c.effects, c.verb, c.verb, c.rules, c.line;
  END LOOP;
END $fk$;

-- app.notes_visible: the rows of app.notes the user may select (line 52: view)
-- mask body (line 53): edit
-- @object view "app"."notes_visible"
DO $mv$
DECLARE cols text; uses text;
BEGIN
  SELECT string_agg(CASE a.attname
      WHEN 'body' THEN format('CASE WHEN %s THEN %I.%I END AS %I', '(coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = "notes"."file_id"))', 'notes', a.attname, a.attname)
      ELSE format('%I.%I', 'notes', a.attname) END, ', ' ORDER BY a.attnum) INTO cols
  FROM pg_attribute a WHERE a.attrelid = '"app"."notes"'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  -- in place when it is there: what the app built on it (a view over it) goes on working
  BEGIN
    EXECUTE format('CREATE OR REPLACE VIEW "app"."notes_visible" WITH (security_barrier) AS SELECT %s FROM "app"."notes" "notes" WHERE %s',
                   cols, '(SELECT authz_int.scope_cmd(''app.notes'', ''select'')) AND EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = "notes"."file_id")');
  EXCEPTION WHEN invalid_table_definition THEN
    -- its columns are not the ones it had (the table's changed): made anew, unless something is built on it
    BEGIN
      DROP VIEW "app"."notes_visible";
    EXCEPTION WHEN dependent_objects_still_exist THEN
      GET STACKED DIAGNOSTICS uses = PG_EXCEPTION_DETAIL;
      RAISE EXCEPTION 'the masked view app.notes_visible can''t be replaced in place: the columns of app.notes changed, and something is built on the view [AZ617]'
        USING DETAIL = uses, HINT = 'drop what is built on it, apply (or run the migration) again, then make it again';
    END;
    EXECUTE format('CREATE VIEW "app"."notes_visible" WITH (security_barrier) AS SELECT %s FROM "app"."notes" "notes" WHERE %s',
                   cols, '(SELECT authz_int.scope_cmd(''app.notes'', ''select'')) AND EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = "notes"."file_id")');
  END;
END $mv$;
COMMENT ON VIEW "app"."notes_visible" IS 'rowstile masked view';
REVOKE ALL ON "app"."notes_visible" FROM PUBLIC;
GRANT SELECT ON "app"."notes_visible" TO "conf_app";

-- Column privileges: masked columns are read through the masked view only. What masks took away is given
-- back first; then what this policy masks is taken away again
DO $mr$
DECLARE r record; cols text;
BEGIN
  FOR r IN SELECT * FROM authz.masked_tables LOOP
    IF to_regclass(r.tbl) IS NOT NULL AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN
      IF r.whole THEN
        -- (taking the table's SELECT back takes the SELECT on its other columns the mask gave instead)
        EXECUTE format('REVOKE SELECT ON %s FROM %I', r.tbl, r.role);
        EXECUTE format('GRANT SELECT ON %s TO %I', r.tbl, r.role);
      END IF;
      SELECT string_agg(format('%I', attname), ', ') INTO cols FROM pg_attribute
      WHERE attrelid = r.tbl::regclass AND attnum > 0 AND NOT attisdropped AND attname = ANY (r.cols);
      IF cols IS NOT NULL THEN EXECUTE format('GRANT SELECT (%s) ON %s TO %I', cols, r.tbl, r.role); END IF;
    END IF;
    DELETE FROM authz.masked_tables WHERE tbl = r.tbl AND role = r.role;
  END LOOP;
END $mr$;
DO $mc$
DECLARE cols text; whole boolean; took text[];
BEGIN
  -- app.notes: body only through app.notes_visible
  whole := has_table_privilege('conf_app', '"app"."notes"', 'SELECT');
  -- (the SELECT of their own the masked columns have, taken away below: given back when the mask goes)
  took := ARRAY(SELECT c FROM unnest(ARRAY['body']) c
                WHERE NOT whole AND has_column_privilege('conf_app', '"app"."notes"', c, 'SELECT'));
  IF whole THEN
    REVOKE SELECT ON "app"."notes" FROM "conf_app";
    SELECT string_agg(format('%I', attname), ', ') INTO cols FROM pg_attribute
    WHERE attrelid = '"app"."notes"'::regclass AND attnum > 0 AND NOT attisdropped
      AND attname <> ALL (ARRAY['body']);
    IF cols IS NOT NULL THEN EXECUTE format('GRANT SELECT (%s) ON "app"."notes" TO "conf_app"', cols); END IF;
  END IF;
  IF whole OR took <> '{}' THEN
    INSERT INTO authz.masked_tables VALUES ('"app"."notes"', 'conf_app', whole, took);
  END IF;
  REVOKE SELECT ("body") ON "app"."notes" FROM "conf_app";
  IF has_column_privilege('conf_app', '"app"."notes"', 'body', 'SELECT') THEN
    RAISE EXCEPTION 'conf_app could still read masked columns of app.notes directly [AZ611]'
      USING HINT = 'SELECT on the table or these columns is granted to PUBLIC or to a role conf_app belongs to; revoke it, then apply again';
  END IF;
END $mc$;

CREATE TABLE authz_int.masked_columns (tbl text, col text, view text, PRIMARY KEY (tbl, col));
INSERT INTO authz_int.masked_columns VALUES ('"app"."notes"', 'body', '"app"."notes_visible"');

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_integer integer;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."folders" o WHERE o."id" = v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"(o."parent_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."folders" o WHERE o."id" = v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR authz_int."folder__view__has"(o."parent_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."files" o WHERE o."id" = v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"(o."folder_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."files" o WHERE o."id" = v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR authz_int."folder__edit__has"(o."folder_id")
    OR (NOT coalesce((confidential), false)
    AND authz_int."folder__view__has"(o."folder_id")))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = v_integer AND ((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = v_integer AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'folder.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."parent_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE o."id" > p_after::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."parent_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE o."id" > p_after::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE o."id" > p_after::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id"))
    OR (NOT coalesce((confidential), false)
    AND (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id"))
    OR (NOT coalesce((confidential), false)
    AND (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"))))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE o."id" > p_after::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id"))
    OR (NOT coalesce((confidential), false)
    AND (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'note.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > p_after::integer AND (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'note.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > p_after::integer AND EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Every permission the user holds on one object: SELECT authz.perms('file', 11)
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE names text[];
BEGIN
  CASE p_type
    WHEN 'user' THEN names := ARRAY[]::text[];
    WHEN 'team' THEN names := ARRAY[]::text[];
    WHEN 'folder' THEN names := ARRAY['edit', 'view']::text[];
    WHEN 'file' THEN names := ARRAY['edit', 'view']::text[];
    WHEN 'note' THEN names := ARRAY['edit', 'view']::text[];
    ELSE RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  RETURN ARRAY(SELECT n FROM unnest(names) n WHERE authz.can(p_type, p_id, n));
END $f$;

-- The permissions the user holds on many objects, in one call (a list's buttons): SELECT * FROM authz.perms_of('folder', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.perms_of(p_type text, p_ids text[]) RETURNS TABLE (id text, perms text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN QUERY SELECT x, authz.perms(p_type, x) FROM unnest(p_ids) WITH ORDINALITY u(x, n) ORDER BY n;
END $f$;
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id integer, p_perm text) RETURNS boolean LANGUAGE sql STABLE AS
  $$ SELECT authz.can(p_type, p_id::text, p_perm) $$;
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id integer) RETURNS text[] LANGUAGE sql STABLE AS
  $$ SELECT authz.perms(p_type, p_id::text) $$;

-- Why the caller may not share (a refusal's DETAIL): authz.explain's answer, as the caller, for each of these
-- permissions the type has, which they may ask for themselves; an id that isn't the type's is answered as a missing
-- object is
CREATE FUNCTION authz_int.share_why(p_type text, p_id text, p_perms text[]) RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RETURN 'no   you have no access to ' || p_type || ' ' || p_id;
  END IF;
  RETURN coalesce((SELECT pg_catalog.string_agg(w.line, pg_catalog.chr(10) ORDER BY u.i, w.j)
                   FROM pg_catalog.unnest(p_perms) WITH ORDINALITY u(perm, i)
                   CROSS JOIN LATERAL authz.explain(p_type, p_id, u.perm) WITH ORDINALITY w(line, j)
                   WHERE EXISTS (SELECT 1 FROM authz_int.perms x WHERE x.type = p_type AND x.perm = u.perm)),
                  'no   the policy shares nothing of ' || p_type);
END $f$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles; v_perms text[];
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, '{}'), HINT = 'rowstile help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    -- why, in what authz.explain tells the caller (a hidden object as a missing one): the permission sharing this
    -- relation takes (a custom role: share), or for a relation the type doesn't share, each one sharing there takes
    v_perms := CASE WHEN p_relation LIKE 'role:%' THEN ARRAY['share'] ELSE coalesce(
      nullif(ARRAY(SELECT DISTINCT s.shared_by FROM authz_int.shared_relations s
                   WHERE s.object_type = p_type AND s.relation = p_relation), '{}'),
      ARRAY(SELECT s.shared_by FROM authz_int.shared_relations s WHERE s.object_type = p_type UNION SELECT 'share')) END;
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, v_perms), HINT = 'rowstile help AZ705';
  END IF;
  v_key := authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation);
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING HINT = 'rowstile help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT authz_int.role_owned(p_type, p_id, v_role.owner_type, v_role.owner_id) THEN
      RAISE EXCEPTION 'role % belongs to % %, which doesn''t own % %', v_role.name, v_role.owner_type, v_role.owner_id,
        p_type, p_id USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
        DETAIL = authz_int.share_why(p_type, p_id, ARRAY['share']), HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', DETAIL = authz_int.share_why(p_type, p_id, string_to_array(v_need, ', ')),
              HINT = 'rowstile help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege',
        DETAIL = authz_int.share_why(p_type, p_id, ARRAY[v_rel.shared_by]), HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', DETAIL = authz_int.share_why(p_type, p_id, string_to_array(v_need, ', ')),
              HINT = 'rowstile help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowstile help AZ707';
  END IF;
  PERFORM authz_int.mark_row(p_type, p_id);
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    PERFORM authz_int.mark_row(p_subject_type, p_subject_id);
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text, p_subject_type text, p_subject_id integer,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id integer, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id integer, p_relation text, p_subject_type text, p_subject_id integer,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;

-- Unshare: needs what sharing needs (the relation's 'shared by' permission)
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_by text;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  v_by := coalesce(authz_int.manage_perm(p_type, p_relation,
                                         authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation)),
                   authz_int.manage_perm(p_type, p_relation));
  -- what it needs comes from the policy alone: the same words for a hidden object and a missing one
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR v_by IS NULL
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_by)
     OR NOT authz.can(p_type, p_id, v_by) THEN
    IF v_by IS NULL THEN
      RAISE EXCEPTION 'you cannot unshare % on % %', p_relation, p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    RAISE EXCEPTION 'you cannot unshare % on % % (needs %)', p_relation, p_type, p_id, v_by USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, ARRAY[v_by]), HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.shares WHERE object_type = p_type AND object_id = p_id
    AND relation = p_relation AND subject_type = p_subject_type
    AND subject_id = p_subject_id AND subject_relation = p_subject_relation;
END $f$;
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id text, p_relation text, p_subject_type text, p_subject_id integer,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation) $$;
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id integer, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation) $$;
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id integer, p_relation text, p_subject_type text, p_subject_id integer,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation) $$;

-- A link anyone holding the token can use: returns the token once (only its hash is stored).
-- Requests present it with SET LOCAL authz_ctx.links = '<token>'.
CREATE OR REPLACE FUNCTION authz.create_link(p_type text, p_id text, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
BEGIN
  PERFORM authz.share(p_type, p_id, p_relation, 'link', encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
                      '', p_expires_at);
  RETURN v_token;
END $f$;
CREATE OR REPLACE FUNCTION authz.create_link(p_type text, p_id integer, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE sql AS $$ SELECT authz.create_link(p_type, p_id::text, p_relation, p_expires_at) $$;

-- The relations whose links on an object the caller may see: every one it has links of if they may inspect it
-- (they can share it, or are an administrator), else those they may share with a link. NULL: none
CREATE FUNCTION authz_int.link_relations(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF authz_int.may_inspect(p_type, p_id) THEN
    RETURN coalesce((SELECT array_agg(DISTINCT g.relation) FROM authz.shares g
                     WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'), '{}');
  END IF;
  RETURN (SELECT array_agg(s.relation) FROM authz_int.shared_relations s
          WHERE s.object_type = p_type AND s.subject = 'link'
            AND authz_int.may_manage(p_type, p_id, s.relation, 'link'));
END $f$;
-- The links on an object: SELECT * FROM authz.list_links('folder', 3). For those who can share it, or may make
-- such links. A link's id names it for authz.revoke_link: it is not the token, and opens nothing.
CREATE OR REPLACE FUNCTION authz.list_links(p_type text, p_id text)
RETURNS TABLE (id text, relation text, created_by text, created_at timestamptz, expires_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_relations text[];
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  v_relations := authz_int.link_relations(p_type, p_id);
  IF v_relations IS NULL THEN
    RAISE EXCEPTION 'you cannot see the links of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT left(g.subject_id, 16), g.relation, g.created_by, g.created_at, g.expires_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
    AND g.relation = ANY (v_relations) ORDER BY g.created_at, g.subject_id;
END $f$;
-- Turn a link off, by its id in authz.list_links: needs what unsharing it needs. A link in several relations is
-- judged in each as things are before any of it goes, and goes whole or not at all: taking it out of one relation
-- may change what the caller holds, and so what the next would be judged on
CREATE OR REPLACE FUNCTION authz.revoke_link(p_type text, p_id text, p_link text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_relations text[]; v record; v_found boolean := false;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  v_relations := authz_int.link_relations(p_type, p_id);
  IF v_relations IS NULL THEN
    RAISE EXCEPTION 'you cannot turn off the links of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  FOR v IN SELECT g.relation FROM authz.shares g
           WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
             AND g.relation = ANY (v_relations) AND left(g.subject_id, 16) = p_link LOOP
    IF NOT authz_int.may_manage(p_type, p_id, v.relation, 'link') THEN
      RAISE EXCEPTION 'you cannot turn off link % of % % (you could not unshare it)', p_link, p_type, p_id
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    v_found := true;
  END LOOP;
  IF NOT v_found THEN
    RAISE EXCEPTION 'no link % on % %', p_link, p_type, p_id USING HINT = 'rowstile help AZ708';
  END IF;
  DELETE FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
    AND g.relation = ANY (v_relations) AND left(g.subject_id, 16) = p_link;
END $f$;
CREATE OR REPLACE FUNCTION authz.list_links(p_type text, p_id integer) RETURNS TABLE (id text, relation text, created_by text, created_at timestamptz, expires_at timestamptz) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.list_links(p_type, p_id::text) $$;
CREATE OR REPLACE FUNCTION authz.revoke_link(p_type text, p_id integer, p_link text) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.revoke_link(p_type, p_id::text, p_link) $$;

-- Custom roles: defined per owner (e.g. an org) by people with 'manage_roles' there
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id text, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.create_role');
  p_owner_id := authz_int.canon(p_owner_type, p_owner_id);
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles') THEN
    RAISE EXCEPTION '% has no manage_roles permission in the policy', p_owner_type USING HINT = 'rowstile help AZ707';
  END IF;
  -- a type without `roles` (or one the policy doesn't have): a role there would be one nobody can be given
  IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_object_type) THEN
    RAISE EXCEPTION 'no custom roles on % in the policy', p_object_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF authz.uid() IS NULL OR NOT authz.can(p_owner_type, p_owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_owner_type IS DISTINCT FROM coalesce(authz_int.role_owner_type(p_object_type), p_owner_type) THEN
    RAISE EXCEPTION 'custom roles on % belong to a % (the policy says where they come from), not to a %',
      p_object_type, authz_int.role_owner_type(p_object_type), p_owner_type USING HINT = 'rowstile help AZ706';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = p_object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'custom roles on % cannot grant %', p_object_type, v_bad USING HINT = 'rowstile help AZ706';
  END IF;
  INSERT INTO authz.roles (owner_type, owner_id, object_type, name, created_by)
  VALUES (p_owner_type, p_owner_id, p_object_type, p_name, authz_int.actor())
  RETURNING id INTO v_id;
  INSERT INTO authz.role_permissions SELECT v_id, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
  RETURN v_id;
END $f$;
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id integer, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.create_role(p_owner_type, p_owner_id::text, p_object_type, p_name, p_permissions) $$;
CREATE OR REPLACE FUNCTION authz.set_role_permissions(p_role bigint, p_permissions text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.set_role_permissions');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = v.object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'custom roles on % cannot grant %', v.object_type, v_bad USING HINT = 'rowstile help AZ706'; END IF;
  DELETE FROM authz.role_permissions WHERE role_id = p_role;
  INSERT INTO authz.role_permissions SELECT p_role, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
END $f$;
CREATE OR REPLACE FUNCTION authz.delete_role(p_role bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.delete_role');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.roles WHERE id = p_role;
END $f$;
CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id text)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.users_only('authz.roles_of');
  p_owner_id := authz_int.canon(p_owner_type, p_owner_id);
  IF authz.uid() IS NULL OR NOT (
       (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles')
        AND authz.can(p_owner_type, p_owner_id, 'manage_roles'))
    OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'view')
        AND authz.can(p_owner_type, p_owner_id, 'view'))) THEN
    RAISE EXCEPTION 'you cannot see roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT r.id, r.object_type, r.name,
    ARRAY(SELECT p.permission FROM authz.role_permissions p WHERE p.role_id = r.id ORDER BY 1)
    FROM authz.roles r WHERE r.owner_type = p_owner_type AND r.owner_id = p_owner_id ORDER BY r.id;
END $f$;
CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id integer)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[]) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.roles_of(p_owner_type, p_owner_id::text) $$;

-- Why a write is or would be refused, as the signed-in user: an insert (p_row: the new row as JSON), or an
-- update or delete of the row whose id is p_id (for an update, p_row: the new values). NULL when that row isn't
-- there or the user can't see it (404, not 403). SELECT authz.explain_rule('app.files', 'update', '11')
CREATE OR REPLACE FUNCTION authz.explain_rule(p_table text, p_command text, p_id text DEFAULT NULL, p_row jsonb DEFAULT NULL)
RETURNS text[] LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_command IS NULL OR p_command NOT IN ('insert', 'update', 'delete') THEN
    RAISE EXCEPTION 'explain_rule explains insert, update or delete, not %', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_table
    WHEN 'app.folders' THEN RETURN authz_gen."app.folders:rules:explain"(p_command, p_id, p_row);
    WHEN 'app.files' THEN RETURN authz_gen."app.files:rules:explain"(p_command, p_id, p_row);
    WHEN 'app.notes' THEN RETURN authz_gen."app.notes:rules:explain"(p_command, p_id, p_row);
    ELSE RAISE EXCEPTION 'the policy has no rules for table %', p_table USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Which of these people (or principals of another type) hold a permission: who to tell about a change.
-- It signs each one in with authz.act_as(), as the caller: so only a backend trusted to sign anyone in can
-- use it, as it could ask authz.can for each one itself. Not in a session limited by scopes or view-as. SELECT * FROM authz.who_among('chat', '7', 'read', ARRAY['1', '2'])
-- (it reads those settings as they are, not through authz_int.scopes_active(), which the app role may not call: the
-- guard only keeps its last act_as, which ends scopes and view-as, from widening the session)
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id text, p_perm text, p_users text[], p_principal_type text DEFAULT 'user')
RETURNS SETOF text LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user');
        v_u text;
BEGIN
  IF coalesce(current_setting('authz.scopes', true), '') <> '' OR coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.who_among() signs people in, which a session limited by scopes or view-as may not'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  FOREACH v_u IN ARRAY coalesce(p_users, '{}') LOOP
    PERFORM authz.act_as(p_principal_type, v_u);
    IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_u; END IF;
  END LOOP;
  PERFORM authz.act_as(v_pt, v_me);
END $f$;
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id integer, p_perm text, p_users text[], p_principal_type text DEFAULT 'user') RETURNS SETOF text LANGUAGE sql VOLATILE AS
  $$ SELECT * FROM authz.who_among(p_type, p_id::text, p_perm, p_users, p_principal_type) $$;

-- these functions call each other; their bodies are checked when first used
SET LOCAL check_function_bodies = off;

CREATE FUNCTION authz_int."team__member__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  WITH RECURSIVE gs(id) AS (SELECT p_id UNION SELECT e.subj FROM (SELECT s."parent_id" AS obj, s."id" AS subj FROM "app"."teams" s WHERE s."id" IS NOT NULL AND s."parent_id" IS NOT NULL) e JOIN gs ON e.obj = gs.id)
  SELECT x FROM gs, LATERAL (SELECT s."user_id" FROM "app"."team_members" s WHERE s."team_id" = gs.id) w(x)
$f$;

CREATE FUNCTION authz_int."folder__owner__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."owner_id" FROM "app"."folders" r WHERE r."id" = p_id AND r."owner_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."folder__team__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM "app"."folder_teams" s, LATERAL authz_int."team__member__who"(s."team_id") x WHERE s."folder_id" = p_id
$f$;

CREATE FUNCTION authz_int."folder__viewer__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT g.subject_id::integer FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id = (p_id)::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*'
$f$;

CREATE FUNCTION authz_int."file__owner__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."owner_id" FROM "app"."files" r WHERE r."id" = p_id AND r."owner_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."file__viewer__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT g.subject_id::integer FROM authz.shares g WHERE g.object_type = 'file' AND g.object_id = (p_id)::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*'
$f$;

CREATE FUNCTION authz_int."note__author__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."author_id" FROM "app"."notes" r WHERE r."id" = p_id AND r."author_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."folder__edit__who_base"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM authz_int."folder__owner__who"(p_id) x
$f$;

CREATE FUNCTION authz_int."folder__edit__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM authz_int."folder__parent__tree" c, LATERAL authz_int."folder__edit__who_base"(c.ancestor) x WHERE c.descendant = p_id
$f$;

CREATE FUNCTION authz_int."folder__view__who_base"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."folder__edit__who"(p_id) x)
  UNION ALL
  (SELECT x FROM authz_int."folder__team__who"(p_id) x)
  UNION ALL
  (SELECT x FROM authz_int."folder__viewer__who"(p_id) x)
$f$;

CREATE FUNCTION authz_int."folder__view__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM authz_int."folder__parent__tree" c, LATERAL authz_int."folder__view__who_base"(c.ancestor) x WHERE c.descendant = p_id
$f$;

CREATE FUNCTION authz_int."file__edit__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."file__owner__who"(p_id) x)
  UNION ALL
  (SELECT x FROM (SELECT r."folder_id" AS id FROM "app"."files" r WHERE r."id" = p_id AND r."folder_id" IS NOT NULL) tg, LATERAL authz_int."folder__edit__who"(tg.id) x)
$f$;

CREATE FUNCTION authz_int."file__view__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."file__edit__who"(p_id) x)
  UNION ALL
  (SELECT x FROM authz_int."file__viewer__who"(p_id) x)
  UNION ALL
  (SELECT x FROM (SELECT r."folder_id" AS id FROM "app"."files" r WHERE r."id" = p_id AND r."folder_id" IS NOT NULL) tg, LATERAL authz_int."folder__view__who"(tg.id) x)
$f$;

CREATE FUNCTION authz_int."note__edit__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."note__author__who"(p_id) x)
  UNION ALL
  (SELECT x FROM (SELECT r."file_id" AS id FROM "app"."notes" r WHERE r."id" = p_id AND r."file_id" IS NOT NULL) tg, LATERAL authz_int."file__edit__who"(tg.id) x)
$f$;

CREATE FUNCTION authz_int."note__view__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM (SELECT r."file_id" AS id FROM "app"."notes" r WHERE r."id" = p_id AND r."file_id" IS NOT NULL) tg, LATERAL authz_int."file__view__who"(tg.id) x
$f$;

CREATE FUNCTION authz_int."team__member__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."team_id" AS id FROM "app"."team_members" s WHERE s."user_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'member: a row in app.team_members names you' || '';
    RETURN;
  END IF;
  FOR v_t IN SELECT e.subj::text AS id FROM (SELECT s."parent_id" AS obj, s."id" AS subj FROM "app"."teams" s WHERE s."id" IS NOT NULL AND s."parent_id" IS NOT NULL) e
             WHERE e.obj = p_id AND EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = e.subj) LIMIT 1 LOOP
    IF NOT ('team:member:' || v_t.id = ANY (p_seen)) THEN
      RETURN NEXT pad || 'yes  through team ' || v_t.id || ', whose member count here too';
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.id::integer, p_depth + 1,
                                 p_seen || ('team:member:' || v_t.id));
      RETURN;
    END IF;
  END LOOP;
  RETURN NEXT pad || 'no   you do not hold team.member';
END $f$;

CREATE FUNCTION authz_int."folder__parent__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN

  RETURN NEXT pad || 'no   you do not hold folder.parent';
END $f$;

CREATE FUNCTION authz_int."folder__owner__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "app"."folders" r WHERE r."owner_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'owner: owner_id is you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold folder.owner';
END $f$;

CREATE FUNCTION authz_int."folder__team__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."folder_id" AS id FROM "app"."folder_teams" s WHERE s."team_id" = ANY ((SELECT authz_int."team__member__ids"())::integer[])) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT s."team_id" AS gid FROM "app"."folder_teams" s WHERE s."folder_id" = p_id AND s."team_id" IN (SELECT id FROM authz_int."team__member")) x LIMIT 1 LOOP
      RETURN NEXT pad || 'yes  ' || 'team: a row in app.folder_teams names' || ' team ' || v_t.gid || ', and you are member there';
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::integer, p_depth + 1, p_seen);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold folder.team';
END $f$;

CREATE FUNCTION authz_int."folder__viewer__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::integer AS id FROM authz.shares g WHERE g.object_type = 'folder' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'viewer: shared with you' || coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '');
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold folder.viewer';
END $f$;

CREATE FUNCTION authz_int."folder__edit__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."folder__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'folder.edit = owner or parent.edit';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."folder__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'owner';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__owner__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."folder__parent__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'parent.edit';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."parent_id" AS id FROM "app"."folders" r WHERE r."id" = p_id AND r."parent_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('folder', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'parent is a folder you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'parent is folder '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has edit' ELSE ', without edit' END;
      IF NOT ('folder:edit:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__edit__why"(v_t.id::integer, p_depth + 1 + 1, p_seen || ('folder:edit:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

CREATE FUNCTION authz_int."folder__view__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."folder__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'folder.view = edit or team or viewer or parent.view';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."folder__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'edit';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__edit__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."folder__team");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'team';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__team__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."folder__viewer");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'viewer';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__viewer__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."folder__parent__view");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'parent.view';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."parent_id" AS id FROM "app"."folders" r WHERE r."id" = p_id AND r."parent_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('folder', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'parent is a folder you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'parent is folder '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has view' ELSE ', without view' END;
      IF NOT ('folder:view:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__view__why"(v_t.id::integer, p_depth + 1 + 1, p_seen || ('folder:view:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

