-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."users" "users" WHERE "users"."id" = p_id::integer
        AND true);
    WHEN 'team' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."teams" "teams" WHERE "teams"."id" = p_id::integer
        AND true);
    WHEN 'folder' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."folders" "folders" WHERE "folders"."id" = p_id::integer
        AND (SELECT authz_int.scope_cmd('app.folders', 'select')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = "folders"."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = "folders"."id")
    OR authz_int."folder__view__has"("folders"."parent_id")));
    WHEN 'file' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."files" "files" WHERE "files"."id" = p_id::integer
        AND (SELECT authz_int.scope_cmd('app.files', 'select')) AND (coalesce("files"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = "files"."id")
    OR authz_int."folder__edit__has"("files"."folder_id")
    OR (NOT coalesce((confidential), false)
    AND authz_int."folder__view__has"("files"."folder_id"))));
    WHEN 'note' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."notes" "notes" WHERE "notes"."id" = p_id::integer
        AND (SELECT authz_int.scope_cmd('app.notes', 'select')) AND EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = "notes"."file_id"));
    ELSE RETURN false;
  END CASE;
END $f$;

-- May the current user look at who has access to this object? (they can share it, or the caller is an
-- administrator: the policy's owner, a superuser or BYPASSRLS)
CREATE FUNCTION authz_int.may_inspect(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF authz_int.caller_is_admin() THEN RETURN true; END IF;
  RETURN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
     AND authz.can(p_type, p_id, 'share');
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked with authz.can, as that user.
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_integer integer;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."folder__edit__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."folder__view__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."file__edit__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."file__view__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."note__edit__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."note__view__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_integer integer;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), '');
BEGIN
  -- the signed-in user's own id is the signed-in user: asked as without it (a service whose id is a user's is not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS NOT DISTINCT FROM authz.uid()::text THEN
    p_user := NULL;
  END IF;
  -- another user's access: only for people who may inspect the object, within their scopes (as authz.who)
  IF p_user IS NOT NULL AND (NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm)) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  IF p_user IS NOT NULL THEN
    PERFORM set_config('authz.user_id', p_user, true);
    PERFORM set_config('authz.principal_type', '', true);
    PERFORM set_config('authz.scopes', '', true);   -- that user's access, with full rights (as authz.who)
    PERFORM authz_int.sign();
  END IF;
  v_ok := authz.can(p_type, p_id, p_perm);
  RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
    || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."folder__edit__why"(v_integer, 1, '{}');
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."folder__view__why"(v_integer, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."file__edit__why"(v_integer, 1, '{}');
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."file__view__why"(v_integer, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."note__edit__why"(v_integer, 1, '{}');
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."note__view__why"(v_integer, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- The shares on an object (for a sharing dialog): SELECT * FROM authz.list_shares('folder', 3)
CREATE OR REPLACE FUNCTION authz.list_shares(p_type text, p_id text)
RETURNS TABLE (relation text, role text, subject_type text, subject_id text, subject_relation text,
               expires_at timestamptz, starts_at timestamptz, caveat text, created_by text, created_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  IF NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot see the shares of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT g.relation, (SELECT r.name FROM authz.roles r WHERE 'role:' || r.id = g.relation),
    g.subject_type, CASE WHEN g.subject_type = 'link' THEN '(link)' ELSE g.subject_id END, g.subject_relation,
    g.expires_at, g.starts_at, g.caveat, g.created_by, g.created_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id ORDER BY g.created_at, g.relation;
END $f$;
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id integer, p_perm text) RETURNS SETOF text LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.who(p_type, p_id::text, p_perm) $$;
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id integer, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.explain(p_type, p_id::text, p_perm, p_user) $$;
CREATE OR REPLACE FUNCTION authz.list_shares(p_type text, p_id integer) RETURNS TABLE (relation text, role text, subject_type text, subject_id text, subject_relation text, expires_at timestamptz, starts_at timestamptz, caveat text, created_by text, created_at timestamptz) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.list_shares(p_type, p_id::text) $$;

-- Invariants: checked as everyone who can sign in (named as the audit trail names them: '42', 'user:a:b',
-- 'service:3') and as nobody; returns the violations
CREATE OR REPLACE FUNCTION authz.check_invariants() RETURNS TABLE (invariant text, user_id text, object_ids text[])
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_p text; v_u text; v_ids text[];
BEGIN
  PERFORM set_config('authz.scopes', '', true);
  FOR v_p, v_u IN SELECT '', '' UNION ALL SELECT '', x."id"::text FROM "app"."users" x LOOP
    PERFORM set_config('authz.principal_type', v_p, true);
    PERFORM set_config('authz.user_id', v_u, true);
    PERFORM authz_int.sign();
    NULL;
  END LOOP;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

SET LOCAL check_function_bodies = on;

-- the keys of principals that are gone, or whose id changed (p_ids; NULL: every one of the type, TRUNCATE) are
-- deleted, each in the audit trail, with the rows' marks (forget_marks: in a transaction whose snapshot may be older
-- than a key made for one of them, that fails to serialize, 40001)
CREATE FUNCTION authz_int.keys_gone(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k record;
BEGIN
  IF p_ids IS NULL THEN
    DELETE FROM authz_int.row_marks WHERE type = p_type;
  ELSE
    PERFORM authz_int.forget_marks(p_type, p_ids);
  END IF;
  FOR k IN DELETE FROM authz.api_keys WHERE principal_type = p_type AND (p_ids IS NULL OR user_id = ANY (p_ids))
           RETURNING id, user_id, name LOOP
    PERFORM authz_int.audit('delete_api_key', p_type, k.user_id, NULL, NULL, NULL, NULL,
                            jsonb_build_object('key', k.id, 'name', k.name, 'why', 'its principal is gone'));
  END LOOP;
END $f$;

-- API keys: a signed-in user's own, or a principal's (a service's) made by someone holding
-- manage_keys on it; only a hash is kept
CREATE OR REPLACE FUNCTION authz.create_api_key(p_name text, p_scopes text DEFAULT '', p_expires_at timestamptz DEFAULT NULL,
  p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := 'ak_' || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
        v_scopes text[] := ARRAY(SELECT DISTINCT btrim(x) FROM unnest(string_to_array(coalesce(p_scopes, ''), ',')) x
                                 WHERE btrim(x) <> '' ORDER BY 1);
        v_cur text[] := authz_int.scopes_active(); v_bad text;
        v_type text := coalesce(p_principal_type, 'user'); v_id text;
BEGIN
  PERFORM authz_int.check_writable();
  -- the principal's row is locked (FOR KEY SHARE) before it is checked: a delete of it waits for this key, or this
  -- for the delete, which leaves no principal to make it for (a delete with an older snapshot: keys_gone)
  IF p_principal_id IS NULL THEN
    PERFORM authz_int.users_only('authz.create_api_key for oneself');
    v_id := authz.uid()::text;
    IF v_type <> 'user' OR v_id IS NULL OR NOT authz_int.hold('user', v_id) THEN
      RAISE EXCEPTION 'sign in to create an API key' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714';
    END IF;
  ELSE
    v_id := authz_int.canon(v_type, p_principal_id);
    -- (no row there: authz.can holds only on rows that are, so the check refuses it, as one you can't manage)
    PERFORM authz_int.hold(v_type, v_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  SELECT string_agg(x, ', ') INTO v_bad FROM unnest(v_scopes) x
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'no scope % in the policy', v_bad USING HINT = 'rowstile help AZ707'; END IF;
  IF v_cur IS NOT NULL AND (cardinality(v_scopes) = 0 OR NOT v_scopes <@ v_cur) THEN
    RAISE EXCEPTION 'a key cannot have more scopes than the session creating it' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  INSERT INTO authz.api_keys (user_id, principal_type, name, prefix, hash, scopes, expires_at)
  VALUES (v_id, v_type, p_name, left(v_token, 10), encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
          array_to_string(v_scopes, ','), p_expires_at);
  PERFORM authz_int.mark_row(v_type, v_id);
  PERFORM authz_int.audit('create_api_key', v_type, v_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('name', p_name, 'scopes', v_scopes, 'expires_at', p_expires_at));
  RETURN v_token;
END $f$;

-- May the signed-in principal manage the keys of this one? Needs `can manage_keys` on its type.
CREATE FUNCTION authz_int.check_manage_keys(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION 'no type % that signs in (type ... principal) in the policy', p_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'manage_keys') THEN
    RAISE EXCEPTION 'the policy gives % no manage_keys permission, so nobody manages its keys', p_type
      USING HINT = 'rowstile help AZ707';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR NOT coalesce(authz.can(p_type, p_id, 'manage_keys'), false) THEN
    RAISE EXCEPTION 'you cannot manage the keys of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
END $f$;

-- Your keys, or (with manage_keys on it) a principal's
CREATE OR REPLACE FUNCTION authz.list_api_keys(p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS TABLE (id bigint, name text, prefix text, scopes text, created_at timestamptz, expires_at timestamptz,
               last_used_at timestamptz, revoked_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text; v_id text;
BEGIN
  IF p_principal_id IS NULL THEN
    SELECT p.principal_type, p.principal_id INTO v_type, v_id FROM authz.principal() p;
  ELSE
    v_type := coalesce(p_principal_type, 'user');
    v_id := authz_int.canon(v_type, p_principal_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  RETURN QUERY SELECT k.id, k.name, k.prefix, k.scopes, k.created_at, k.expires_at, k.last_used_at, k.revoked_at
  FROM authz.api_keys k WHERE k.user_id = v_id AND k.principal_type = v_type ORDER BY k.id;
END $f$;

-- Revoke a key: your own, a user's you may inspect, or a principal's you manage the keys of
CREATE OR REPLACE FUNCTION authz.revoke_api_key(p_id bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO k FROM authz.api_keys WHERE id = p_id AND revoked_at IS NULL;
  IF k.id IS NULL OR NOT (
       EXISTS (SELECT 1 FROM authz.principal() p WHERE p.principal_type = k.principal_type AND p.principal_id = k.user_id)
       OR (k.principal_type = 'user' AND authz_int.may_inspect('user', k.user_id))
       OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = k.principal_type AND perm = 'manage_keys')
           AND EXISTS (SELECT 1 FROM authz.principal())
           AND coalesce(authz.can(k.principal_type, k.user_id, 'manage_keys'), false))) THEN
    RAISE EXCEPTION 'no API key % of yours', p_id USING HINT = 'rowstile help AZ708';
  END IF;
  UPDATE authz.api_keys SET revoked_at = now() WHERE id = p_id;
  PERFORM authz_int.audit('revoke_api_key', k.principal_type, k.user_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('key', p_id));
END $f$;

-- Say who is asking, for this transaction: SELECT authz.act_as('user', '42') (NULL, NULL: nobody), first in each
-- transaction. For the app's backend, which signs people in itself; the session is signed, so nothing but this
-- and the logins can change who is signed in. The app role (and its members) may call it.
CREATE OR REPLACE FUNCTION authz.act_as(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_id IS NOT NULL AND coalesce(p_type, 'user') <> 'user'
     AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION '% is not a type that signs in', p_type USING
      HINT = 'principal types are marked "principal" in the policy: type service = app.services principal (rowstile help AZ707)';
  END IF;
  -- stored as every other id is ('05' is 5), so the audit and created_by name the user as shares do
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon(coalesce(p_type, 'user'), p_id), ''), true);
  PERFORM set_config('authz.principal_type', CASE WHEN p_id IS NULL OR coalesce(p_type, 'user') = 'user' THEN '' ELSE p_type END, true);
  PERFORM set_config('authz.scopes', '', true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  PERFORM authz_int.jit_off();
END $f$;

-- Sign in with an API key for this transaction: SELECT authz.login_key('ak_...'). Returns who:
-- a user's id, or type:id for another principal
CREATE OR REPLACE FUNCTION authz.login_key(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  SELECT * INTO k FROM authz.api_keys WHERE hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex');
  IF k.id IS NULL OR k.revoked_at IS NOT NULL OR (k.expires_at IS NOT NULL AND k.expires_at <= now()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM set_config('authz.user_id', k.user_id, true);
  PERFORM set_config('authz.principal_type', CASE WHEN k.principal_type = 'user' THEN '' ELSE k.principal_type END, true);
  PERFORM set_config('authz.scopes', k.scopes, true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  -- when it was last used, to the minute: never waiting on another request with the key (the row they
  -- lock), and not at all in a read-only transaction (a replica, a GET)
  IF pg_catalog.current_setting('transaction_read_only') = 'off' THEN
    UPDATE authz.api_keys SET last_used_at = now()
    WHERE id = (SELECT x.id FROM authz.api_keys x
                WHERE x.id = k.id AND (x.last_used_at IS NULL OR x.last_used_at < now() - interval '1 minute')
                FOR UPDATE SKIP LOCKED);
  END IF;
  PERFORM authz_int.jit_off();
  RETURN authz_int.actor();
END $f$;

-- HMAC-SHA256 in SQL, for JWT signatures (HS256)
CREATE FUNCTION authz_int.hmac_sha256(p_key bytea, p_msg bytea) RETURNS bytea
LANGUAGE plpgsql IMMUTABLE STRICT AS $f$
DECLARE k bytea := p_key; ipad bytea; opad bytea;
BEGIN
  IF length(k) > 64 THEN k := sha256(k); END IF;
  k := k || decode(repeat('00', 64 - length(k)), 'hex');
  ipad := k; opad := k;
  FOR i IN 0..63 LOOP
    ipad := set_byte(ipad, i, get_byte(k, i) # 54);
    opad := set_byte(opad, i, get_byte(k, i) # 92);
  END LOOP;
  RETURN sha256(opad || sha256(ipad || p_msg));
END $f$;
CREATE FUNCTION authz_int.b64url(p text) RETURNS bytea
LANGUAGE sql IMMUTABLE STRICT AS $f$
  SELECT decode(rpad(translate(p, '-_', '+/'), ((length(p) + 3) / 4) * 4, '='), 'base64') $f$;

-- Sign in with a JWT (HS256) for this transaction: SELECT authz.login_jwt('eyJ...')
-- Settings (authz.settings): jwt_secret (required), jwt_issuer, jwt_audience, jwt_user_claim (default sub),
-- jwt_type_claim (a claim naming the principal's type, for services; absent or 'user': a user).
-- Tokens must carry exp.
-- A 'scope' claim (space separated) limits the transaction to those policy scopes.
CREATE OR REPLACE FUNCTION authz.login_jwt(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE parts text[] := string_to_array(coalesce(p_token, ''), '.'); v_head jsonb; v_claims jsonb; v_secret text;
        v_user text; v_type text; v_scopes text[]; v_now numeric := extract(epoch FROM now()); v_want text;
BEGIN
  SELECT value INTO v_secret FROM authz.settings WHERE key = 'jwt_secret';
  IF v_secret IS NULL THEN RAISE EXCEPTION 'JWT login is not configured (authz.settings jwt_secret)' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703'; END IF;
  BEGIN
    IF cardinality(parts) <> 3 THEN RAISE EXCEPTION 'bad'; END IF;
    v_head := convert_from(authz_int.b64url(parts[1]), 'UTF8')::jsonb;
    v_claims := convert_from(authz_int.b64url(parts[2]), 'UTF8')::jsonb;
    -- the signatures compared through their hashes: the time it takes says nothing of how much of the token's is right
    IF v_head->>'alg' IS DISTINCT FROM 'HS256'
       OR sha256(authz_int.b64url(parts[3]))
          IS DISTINCT FROM sha256(authz_int.hmac_sha256(convert_to(v_secret, 'UTF8'),
                                                        convert_to(parts[1] || '.' || parts[2], 'UTF8'))) THEN
      RAISE EXCEPTION 'bad';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END;
  -- an expiry is required; both are numbers of seconds
  IF jsonb_typeof(v_claims->'exp') IS DISTINCT FROM 'number' OR (v_claims->>'exp')::numeric <= v_now
     OR (v_claims ? 'nbf' AND (jsonb_typeof(v_claims->'nbf') <> 'number' OR (v_claims->>'nbf')::numeric > v_now)) THEN
    RAISE EXCEPTION 'token expired or not yet valid' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_issuer';
  IF v_want IS NOT NULL AND v_claims->>'iss' IS DISTINCT FROM v_want THEN
    RAISE EXCEPTION 'token from another issuer' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_audience';
  -- (coalesce: without the claim both sides are NULL, and a token that names no audience is not for this one)
  IF v_want IS NOT NULL AND NOT coalesce(v_claims->>'aud' = v_want
       OR (jsonb_typeof(v_claims->'aud') = 'array' AND v_claims->'aud' ? v_want), false) THEN
    RAISE EXCEPTION 'token for another audience' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := v_claims->>coalesce((SELECT value FROM authz.settings WHERE key = 'jwt_user_claim'), 'sub');
  v_type := v_claims->>(SELECT value FROM authz.settings WHERE key = 'jwt_type_claim');
  IF coalesce(v_type, 'user') <> 'user' AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = v_type AND principal) THEN
    RAISE EXCEPTION 'the token names a type that does not sign in' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon(coalesce(v_type, 'user'), v_user), ''), true);
  PERFORM set_config('authz.principal_type', CASE WHEN coalesce(v_type, 'user') = 'user' THEN '' ELSE v_type END, true);
  PERFORM set_config('authz.acting_user', '', true);
  IF v_claims ? 'scope' THEN
    v_scopes := ARRAY(SELECT x FROM unnest(string_to_array(v_claims->>'scope', ' ')) x
                      WHERE EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x));
    PERFORM set_config('authz.scopes', CASE WHEN cardinality(v_scopes) = 0 THEN '(none)'
                                            ELSE array_to_string(v_scopes, ',') END, true);
  ELSE
    PERFORM set_config('authz.scopes', '', true);
  END IF;
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'the token names no active user' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM authz_int.jit_off();
  RETURN authz_int.actor();
END $f$;

-- Support staff see what a user sees, read-only, for this transaction, with a reason on record:
-- SELECT authz.view_as('42', 'ticket 1234')  (the user type has no impersonate permission: administrators only)
-- A session limited by scopes (a key's, a token's) keeps them: viewing never reads more than the session could.
CREATE OR REPLACE FUNCTION authz.view_as(p_user text, p_reason text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_actor text := authz_int.actor();
        v_scopes text[] := authz_int.scopes_active();  -- the session's, before it is switched
BEGIN
  PERFORM authz_int.users_only('authz.view_as');
  IF coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'already viewing as someone' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'say why (the reason is kept in the audit trail)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT (authz_int.caller_is_admin()
          ) THEN
    RAISE EXCEPTION 'you cannot view as user %', p_user USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon('user', p_user), ''), true);
  PERFORM set_config('authz.principal_type', '', true);
  PERFORM authz_int.sign();
  IF authz.uid() IS NULL THEN
    RAISE EXCEPTION 'there is no active user %', p_user USING HINT = 'rowstile help AZ708';
  END IF;
  PERFORM set_config('authz.acting_user', coalesce(v_actor, authz_int.caller_role()), true);
  PERFORM set_config('authz.scopes', CASE WHEN v_scopes IS NULL THEN 'read'
                                          WHEN cardinality(v_scopes) = 0 THEN '(none)'
                                          ELSE array_to_string(v_scopes, ',') END, true);
  PERFORM authz_int.sign();
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.jit_off();
  PERFORM authz_int.audit('view_as', 'user', authz_int.canon('user', p_user), NULL, NULL, NULL, NULL, NULL);
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  -- NULL is no list: it would remove every member (a sync job's failed fetch, a missing field)
  IF p_members IS NULL OR EXISTS (SELECT 1 FROM unnest(p_members) x WHERE x IS NULL) THEN
    RAISE EXCEPTION 'say who the members are: a list of ids with no NULL in it (an empty list for none)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_type || '.' || p_relation
    WHEN 'team.member' THEN
      WITH want AS (SELECT DISTINCT x::integer AS m FROM unnest(p_members) x),
      del AS (DELETE FROM "app"."team_members" s WHERE s."team_id" = p_id::integer AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "app"."team_members" ("team_id", "user_id") SELECT p_id::integer, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "app"."team_members" s WHERE s."team_id" = p_id::integer AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, p_id, p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    PERFORM authz_int.keys_gone('user', NULL);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;
CREATE FUNCTION authz_int."user__keys_gone_id"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  PERFORM authz_int.keys_gone('user', ARRAY[OLD."id"::text]);
  RETURN NULL;
END $f$;
-- before TRUNCATE empties the table: with a snapshot older than a key made for one of its rows, fail to serialize
CREATE FUNCTION authz_int."user__keys_gone_all"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT x."id"::text FROM "app"."users" x));
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_user_keys_gone_del" AFTER DELETE ON "app"."users"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"();
CREATE TRIGGER "authz_user_keys_gone_id" AFTER UPDATE ON "app"."users" FOR EACH ROW
  WHEN (OLD."id" IS DISTINCT FROM NEW."id") EXECUTE FUNCTION authz_int."user__keys_gone_id"();
CREATE TRIGGER "authz_user_keys_gone_trunc" AFTER TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"();
CREATE TRIGGER "authz_user_keys_gone_trunc_first" BEFORE TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone_all"();
-- On a partitioned table, an update that puts a row in another partition is a delete there and an insert here:
-- Postgres runs no AFTER UPDATE row trigger for it. The ids an update leaves no row with lose their keys too.
-- @object trigger "authz_user_keys_gone_moved" ON "app"."users"
-- @if partitioned
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_catalog.pg_class WHERE oid = '"app"."users"'::regclass) = 'p' THEN
    EXECUTE 'CREATE TRIGGER "authz_user_keys_gone_moved" AFTER UPDATE ON "app"."users" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"()';
  END IF;
END $tr$;

-- Who may manage a relation on an object: the permission that shares it (with users, when asked)
CREATE FUNCTION authz_int.manage_perm(p_type text, p_relation text, p_subject text DEFAULT NULL) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT CASE
    WHEN p_relation LIKE 'role:%' THEN
      CASE WHEN EXISTS (SELECT 1 FROM authz.roles r WHERE 'role:' || r.id = p_relation AND r.object_type = p_type)
                AND EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share') THEN 'share' END
    ELSE (SELECT min(s.shared_by) FROM authz_int.shared_relations s JOIN authz_int.perms pm
            ON pm.type = s.object_type AND pm.perm = s.shared_by
          WHERE s.object_type = p_type AND s.relation = p_relation AND (p_subject IS NULL OR s.subject = p_subject))
  END $f$;
CREATE FUNCTION authz_int.may_manage(p_type text, p_id text, p_relation text, p_subject text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_perm text := authz_int.manage_perm(p_type, p_relation, p_subject);
BEGIN
  IF authz_int.caller_is_admin() THEN RETURN true; END IF;
  RETURN v_perm IS NOT NULL AND EXISTS (SELECT 1 FROM authz.principal()) AND coalesce(authz.can(p_type, p_id, v_perm), false);
END $f$;

-- Ask for access: SELECT authz.request_access('folder', '3', 'viewer', 'for the audit', '7 days')
CREATE OR REPLACE FUNCTION authz.request_access(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_tbl text; v_there boolean;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.request_access');
  -- the requester's row is locked (FOR KEY SHARE) before it is checked, and the object's if it is there (without
  -- saying whether it is): a delete of either waits for the request, or the request for the delete (then the
  -- requester is nobody, or the object is gone: requests_gone)
  IF authz.uid() IS NOT NULL THEN
    PERFORM authz_int.hold('user', authz.uid()::text);
  END IF;
  IF authz.uid() IS NULL THEN RAISE EXCEPTION 'sign in first' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714'; END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why you need it' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NOT NULL AND p_duration <= interval '0' THEN RAISE EXCEPTION 'the duration must be positive' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  SELECT tbl INTO v_tbl FROM authz_int.types WHERE name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF authz_int.manage_perm(p_type, p_relation, CASE WHEN p_relation LIKE 'role:%' THEN NULL ELSE 'user' END) IS NULL
     OR (p_relation LIKE 'role:%' AND NOT EXISTS (SELECT 1 FROM authz_int.role_subjects
                                                  WHERE object_type = p_type AND subject = 'user')) THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  -- no check that the object exists: that would tell people which hidden objects do. A request
  -- for a missing object simply never reaches anyone who could approve it.
  v_there := authz_int.hold(p_type, p_id);
  INSERT INTO authz.requests (object_type, object_id, relation, requester, reason, duration)
  VALUES (p_type, p_id, p_relation, authz.uid()::text, p_reason, p_duration) RETURNING id INTO v_id;
  -- marked: a delete of the requester, or of the object, that can't see this request fails to serialize
  PERFORM authz_int.mark_row('user', authz.uid()::text);
  IF v_there THEN
    PERFORM authz_int.mark_row(p_type, p_id);
  END IF;
  PERFORM authz_int.audit('request_access', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('request', v_id, 'duration', p_duration));
  PERFORM pg_notify('authz_requests', v_id::text);
  RETURN v_id;
END $f$;
CREATE OR REPLACE FUNCTION authz.request_access(p_type text, p_id integer, p_relation text, p_reason text,
  p_duration interval DEFAULT NULL) RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.request_access(p_type, p_id::text, p_relation, p_reason, p_duration) $$;

-- A pending request goes when its requester's row goes, or its object's (deleted, given a new id, emptied out with
-- its table: p_ids NULL), so that it never reaches whoever later has that id; it is kept, cancelled, with why.
-- Decided requests are history, and stay as they were
CREATE FUNCTION authz_int.requests_gone(p_type text, p_ids text[]) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  UPDATE authz.requests r SET status = 'cancelled', decided_at = now(),
    note = CASE WHEN r.object_type = p_type AND (p_ids IS NULL OR r.object_id = ANY (p_ids))
                THEN 'its object is gone' ELSE 'its requester is gone' END
  WHERE r.status = 'pending'
    AND ((r.object_type = p_type AND (p_ids IS NULL OR r.object_id = ANY (p_ids)))
         OR (p_type = 'user' AND (p_ids IS NULL OR r.requester = ANY (p_ids)))) $f$;

-- Requests the current user may decide (they may share that relation on the object), and their own
CREATE OR REPLACE FUNCTION authz.pending_requests()
RETURNS TABLE (id bigint, object_type text, object_id text, relation text, requester text, reason text,
               duration interval, created_at timestamptz, mine boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.users_only('authz.pending_requests');
  RETURN QUERY
  SELECT r.id, r.object_type, r.object_id, r.relation, r.requester, r.reason, r.duration, r.created_at,
         r.requester = authz.uid()::text
  FROM authz.requests r
  WHERE r.status = 'pending' AND authz.uid() IS NOT NULL
    AND (r.requester = authz.uid()::text
         OR (r.requester IS DISTINCT FROM authz.uid()::text
             AND authz_int.may_manage(r.object_type, r.object_id, r.relation,
                                      CASE WHEN r.relation LIKE 'role:%' THEN NULL ELSE 'user' END)))
  ORDER BY r.id;
END $f$;

-- Approve (it becomes a share, made by you, that ends after the requested time) or deny
CREATE OR REPLACE FUNCTION authz.decide_request(p_id bigint, p_approve boolean, p_note text DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.requests;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.decide_request');
  IF authz.uid() IS NULL THEN RAISE EXCEPTION 'sign in to decide a request' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714'; END IF;
  IF p_approve IS NULL THEN RAISE EXCEPTION 'approve (true) or deny (false)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  SELECT * INTO r FROM authz.requests WHERE id = p_id AND status = 'pending' FOR UPDATE;
  IF r.id IS NULL THEN RAISE EXCEPTION 'no pending request %', p_id USING HINT = 'rowstile help AZ708'; END IF;
  IF r.requester = authz.uid()::text THEN
    RAISE EXCEPTION 'you cannot decide your own request' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF NOT authz_int.may_manage(r.object_type, r.object_id, r.relation,
                              CASE WHEN r.relation LIKE 'role:%' THEN NULL ELSE 'user' END) THEN
    RAISE EXCEPTION 'you cannot decide request %', p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_approve THEN
    -- authz.share checks again that you may share it, and that you hold what it grants
    PERFORM authz.share(r.object_type, r.object_id, r.relation, 'user', r.requester, '',
                        CASE WHEN r.duration IS NULL THEN NULL ELSE now() + r.duration END);
  END IF;
  UPDATE authz.requests SET status = CASE WHEN p_approve THEN 'approved' ELSE 'denied' END,
    decided_by = authz_int.actor(), decided_at = now(), note = p_note WHERE id = p_id;
  PERFORM authz_int.audit(CASE WHEN p_approve THEN 'approve_request' ELSE 'deny_request' END, r.object_type,
    r.object_id, r.relation, 'user', r.requester, '', jsonb_build_object('request', p_id, 'note', p_note));
END $f$;
-- Withdraw your own request; recorded as a decision is
CREATE OR REPLACE FUNCTION authz.cancel_request(p_id bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.requests;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.cancel_request');
  UPDATE authz.requests SET status = 'cancelled', decided_at = now()
  WHERE id = p_id AND status = 'pending' AND requester = authz.uid()::text RETURNING * INTO r;
  IF r.id IS NULL THEN RAISE EXCEPTION 'no pending request % of yours', p_id USING HINT = 'rowstile help AZ708'; END IF;
  PERFORM authz_int.audit('cancel_request', r.object_type, r.object_id, r.relation, 'user', r.requester, '',
                          jsonb_build_object('request', p_id));
END $f$;

-- Emergency access: people who hold 'break_glass' on an object give themselves a relation on it
-- for a short time (one day at most); it is audited and announced on channel authz_alerts
-- (the notification carries the audit row's id; the details stay in authz.audit)
CREATE OR REPLACE FUNCTION authz.break_glass(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT interval '1 hour') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE g authz.shares; v_until timestamptz; v_audit bigint; v_held boolean;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.break_glass');
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why (it is kept in the audit trail)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NULL OR p_duration <= interval '0' OR p_duration > interval '1 day' THEN
    RAISE EXCEPTION 'emergency access lasts more than nothing and one day at most' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  -- the object and the user are locked (FOR KEY SHARE), as authz.share locks them: a delete waits for this, or this
  -- for it and then finds nothing to break into
  v_held := authz.uid() IS NOT NULL;
  IF v_held THEN v_held := authz_int.hold(p_type, p_id); END IF;
  IF v_held THEN v_held := authz_int.hold('user', authz.uid()::text); END IF;
  IF NOT v_held
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'break_glass')
     OR NOT authz.can(p_type, p_id, 'break_glass') THEN
    RAISE EXCEPTION 'you cannot break the glass on % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz_int.shared_relations WHERE object_type = p_type AND relation = p_relation
                 AND subject = 'user') THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  v_until := now() + p_duration;
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.mark_row(p_type, p_id);
  PERFORM authz_int.mark_row('user', authz.uid()::text);
  SELECT * INTO g FROM authz.shares WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
    AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '' FOR UPDATE;
  IF g.object_id IS NULL THEN
    INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                              expires_at, created_by)
    VALUES (p_type, p_id, p_relation, 'user', authz.uid()::text, '', v_until, authz_int.actor());
  ELSIF g.caveat IS NOT NULL OR (g.starts_at IS NOT NULL AND g.starts_at > now())
        OR (g.expires_at IS NOT NULL AND g.expires_at < v_until) THEN
    -- a share that would not let them in now becomes an unconditional one until then (the old one is in the audit)
    UPDATE authz.shares SET expires_at = CASE WHEN g.expires_at IS NULL THEN v_until ELSE greatest(g.expires_at, v_until) END,
      starts_at = NULL, caveat = NULL, caveat_args = NULL
    WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
      AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '';
  END IF;
  PERFORM authz_int.audit('break_glass', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('until', v_until, 'previous_share', CASE WHEN g.object_id IS NULL THEN NULL
                                             ELSE to_jsonb(g) - 'subject_id' END));
  SELECT max(id) INTO v_audit FROM authz.audit WHERE action = 'break_glass' AND txid = txid_current();
  PERFORM pg_notify('authz_alerts', json_build_object('audit_id', v_audit, 'action', 'break_glass')::text);
END $f$;
CREATE OR REPLACE FUNCTION authz.break_glass(p_type text, p_id integer, p_relation text, p_reason text,
  p_duration interval DEFAULT interval '1 hour') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.break_glass(p_type, p_id::text, p_relation, p_reason, p_duration) $$;

-- Access reviews: snapshot the shares on an object; reviewers keep or revoke each; closing applies it.
-- Starting one needs 'share' on the object (or being an administrator); revoking an item needs
-- what unsharing it needs.
-- Reviews are for users: a service signed in is refused (users_only).
CREATE OR REPLACE FUNCTION authz.start_review(p_type text, p_id text, p_closes_at timestamptz DEFAULT now() + interval '14 days')
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.start_review');
  IF NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot review % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  INSERT INTO authz.reviews (object_type, object_id, created_by, closes_at)
  VALUES (p_type, p_id, authz_int.actor(), p_closes_at) RETURNING id INTO v_id;
  INSERT INTO authz.review_items (review_id, item, relation, subject_type, subject_id, subject_relation, expires_at)
  SELECT v_id, row_number() OVER (ORDER BY g.created_at, g.relation, g.subject_type, g.subject_id), g.relation,
         g.subject_type, g.subject_id, g.subject_relation, g.expires_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id;
  PERFORM authz_int.audit('start_review', p_type, p_id, NULL, NULL, NULL, NULL, jsonb_build_object('review', v_id));
  RETURN v_id;
END $f$;
CREATE OR REPLACE FUNCTION authz.start_review(p_type text, p_id integer, p_closes_at timestamptz DEFAULT now() + interval '14 days')
RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.start_review(p_type, p_id::text, p_closes_at) $$;
CREATE OR REPLACE FUNCTION authz.review_items(p_review bigint)
RETURNS TABLE (item int, relation text, subject_type text, subject_id text, subject_relation text,
               expires_at timestamptz, keep boolean, decided_by text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews;
BEGIN
  PERFORM authz_int.users_only('authz.review_items');
  SELECT * INTO v FROM authz.reviews WHERE id = p_review;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot see review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT i.item, i.relation, i.subject_type,
    CASE WHEN i.subject_type = 'link' THEN '(link)' ELSE i.subject_id END, i.subject_relation, i.expires_at, i.keep,
    i.decided_by FROM authz.review_items i WHERE i.review_id = p_review ORDER BY i.item;
END $f$;
CREATE OR REPLACE FUNCTION authz.review_decide(p_review bigint, p_item int, p_keep boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews; i authz.review_items;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.review_decide');
  SELECT * INTO v FROM authz.reviews WHERE id = p_review AND closed_at IS NULL;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot decide in review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT * INTO i FROM authz.review_items WHERE review_id = p_review AND item = p_item;
  IF i.item IS NULL THEN RAISE EXCEPTION 'no item % in review %', p_item, p_review USING HINT = 'rowstile help AZ708'; END IF;
  IF NOT authz_int.may_manage(v.object_type, v.object_id, i.relation,
                              authz_int.subject_key(i.subject_type, i.subject_id, i.subject_relation)) THEN
    RAISE EXCEPTION 'you cannot decide on % in review % (you could not unshare it)', i.relation, p_review
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  UPDATE authz.review_items SET keep = p_keep, decided_by = authz_int.actor(), decided_at = now()
  WHERE review_id = p_review AND item = p_item;
END $f$;
-- Close: revoke what reviewers marked (and, if asked, whatever nobody decided and you could unshare)
CREATE OR REPLACE FUNCTION authz.close_review(p_review bigint, p_revoke_undecided boolean DEFAULT false) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews; n int;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.close_review');
  SELECT * INTO v FROM authz.reviews WHERE id = p_review AND closed_at IS NULL FOR UPDATE;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot close review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  PERFORM set_config('authz_ctx.reason', 'access review ' || p_review, true);
  -- items marked 'revoke' were decided by someone allowed to unshare them; undecided ones need you to be
  DELETE FROM authz.shares g USING authz.review_items i
  WHERE i.review_id = p_review
    AND (i.keep = false OR (p_revoke_undecided AND i.keep IS NULL
         AND authz_int.may_manage(v.object_type, v.object_id, i.relation,
                                  authz_int.subject_key(i.subject_type, i.subject_id, i.subject_relation))))
    AND g.object_type = v.object_type AND g.object_id = v.object_id AND g.relation = i.relation
    AND g.subject_type = i.subject_type AND g.subject_id = i.subject_id AND g.subject_relation = i.subject_relation;
  GET DIAGNOSTICS n = ROW_COUNT;
  UPDATE authz.reviews SET closed_at = now() WHERE id = p_review;
  PERFORM authz_int.audit('close_review', v.object_type, v.object_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('review', p_review, 'revoked', n));
  RETURN n;
END $f$;

-- The triggers above that a table under their table lacks, and the statement that makes each
CREATE FUNCTION authz_int.child_triggers() RETURNS TABLE (child regclass, name name, stmt text)
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS $f$
  WITH RECURSIVE below(top, oid) AS (
    SELECT i.inhparent, i.inhrelid FROM pg_inherits i
    UNION SELECT b.top, i.inhrelid FROM pg_inherits i JOIN below b ON i.inhparent = b.oid
  )
  SELECT b.oid::regclass, g.tgname,
         overlay(d.def PLACING ' ON ' || c.name || ' ' FROM strpos(d.def, ' ON ' || p.name || ' ')
                 FOR length(' ON ' || p.name || ' '))
  FROM below b
  JOIN pg_class u ON u.oid = b.oid
  JOIN pg_trigger g ON g.tgrelid = b.top AND NOT g.tgisinternal
   AND CASE WHEN g.tgtype & 1 = 1 THEN NOT u.relispartition         -- a row trigger: Postgres copies it to partitions
            ELSE g.tgtype & 28 <> 0 AND u.relkind IN ('r', 'p') END -- a statement trigger: not for TRUNCATE alone
  JOIN pg_proc f ON f.oid = g.tgfoid AND f.pronamespace = 'authz_int'::regnamespace
  CROSS JOIN LATERAL (SELECT pg_get_triggerdef(g.oid) AS def) d
  CROSS JOIN LATERAL (SELECT format('%I.%I', n.nspname, k.relname) AS name
                      FROM pg_class k JOIN pg_namespace n ON n.oid = k.relnamespace WHERE k.oid = b.top) p
  CROSS JOIN LATERAL (SELECT format('%I.%I', n.nspname, k.relname) AS name
                      FROM pg_class k JOIN pg_namespace n ON n.oid = k.relnamespace WHERE k.oid = b.oid) c
  WHERE NOT EXISTS (SELECT 1 FROM pg_description x WHERE x.objoid = g.oid AND x.classoid = 'pg_trigger'::regclass
                    AND x.description = 'rowstile: the trigger of the table above, for the rows stored here')
    AND NOT EXISTS (SELECT 1 FROM pg_trigger h WHERE h.tgrelid = b.oid AND h.tgname = g.tgname)
$f$;

-- The search path the functions that evaluate the policy's own SQL run with (SET search_path FROM CURRENT)
CREATE FUNCTION authz_int.policy_path() RETURNS name[]
LANGUAGE sql STABLE SET search_path FROM CURRENT AS $f$ SELECT pg_catalog.current_schemas(false) $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('"conf_app"');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'conf_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'conf_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'conf_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- the policy's owner (or a member of it): its sessions are believed unsigned, it may read rowstile's tables
  -- (the session key among them) and turn row-level security off (applying refuses it, AZ624: this finds a grant made since)
  FOR r IN SELECT n.nspowner::regrole AS owner FROM pg_namespace n, pg_roles a
           WHERE n.nspname = 'authz_int' AND a.oid = v_role AND NOT a.rolsuper AND pg_has_role(v_role, n.nspowner, 'MEMBER') LOOP
    severity := 'error'; object := 'conf_app';
    problem := format('is the policy''s owner %s, or a member of it: who is signed in is believed without a signature, and it may read rowstile''s tables and turn row-level security off. The app role must be a role of its own: not the tables'' owner or the policy''s, nor a member of either', r.owner);
    RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."file__view"', 'authz_int."file__viewer"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."folder__team"', 'authz_int."folder__view"', 'authz_int."folder__viewer"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.files:column owner_id:items"', '"app.files:column owner_id:why"', '"app.files:insert:items"', '"app.files:insert:refuse"', '"app.files:insert:why"', '"app.files:rules:explain"', '"app.files:update:items"', '"app.files:update:refuse"', '"app.files:update:why"', '"app.folders:column parent_id after:items"', '"app.folders:column parent_id after:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.notes:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, integer, text)', 'authz.explain(text, integer, text, text)', 'authz.list_shares(text, integer)', 'authz.list_links(text, integer)', 'authz.revoke_link(text, integer, text)', 'authz.create_link(text, integer, text, timestamptz)', 'authz.create_role(text, integer, text, text, text[])', 'authz.roles_of(text, integer)', 'authz.request_access(text, integer, text, text, interval)', 'authz.break_glass(text, integer, text, text, interval)', 'authz.start_review(text, integer, timestamptz)', 'authz.can(text, integer, text)', 'authz.who_among(text, integer, text, text[], text)', 'authz.perms(text, integer)', 'authz.share(text, text, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, integer, text)', 'authz.share(text, integer, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, text, text)', 'authz.share(text, integer, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, integer, text)']::regprocedure[]))
UNION ALL
SELECT n.nspname::text, gw.who, a.privilege_type,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who)
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname = 'authz_sync' AND a.grantee <> n.nspowner
    AND NOT (a.grantee = to_regrole('"conf_zero"') AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON TABLE %s FROM %s CASCADE', a.privilege_type, c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND a.grantee <> c.relowner
    AND NOT (a.grantee = to_regrole('"conf_zero"') AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND att.attacl IS NOT NULL LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowstile''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- the audit trail's guard, which fires in every replication role (ENABLE ALWAYS): ENABLE TRIGGER ALL, which a
  -- data-only pg_restore --disable-triggers ends with, puts it back for ordinary sessions only
  FOR r IN SELECT t.name, g.tgenabled::text AS mode
           FROM (VALUES ('authz_audit_append_only'), ('authz_audit_no_truncate')) t (name)
           LEFT JOIN pg_trigger g ON g.tgrelid = 'authz.audit'::regclass AND g.tgname = t.name
           WHERE g.tgenabled IS DISTINCT FROM 'A' LOOP
    severity := 'warning'; object := 'authz.audit';
    problem := format('the trigger %s %s. rowstile reapply puts it back, in every replication role', r.name,
      CASE r.mode
        WHEN 'O' THEN 'guards it in ordinary sessions only: one with session_replication_role = replica may change the trail (ENABLE TRIGGER ALL leaves it so, as at the end of a data-only pg_restore --disable-triggers)'
        WHEN 'R' THEN 'guards it with session_replication_role = replica only: an ordinary session may change the trail'
        WHEN 'D' THEN 'that guards it is off: the trail may be changed'
        ELSE 'that guards it is missing: the trail may be changed' END);
    RETURN NEXT;
  END LOOP;
  -- the sync role (a preview): the engine reads every row as it, by logical replication
  DECLARE
    v_sync_name text := 'conf_zero';
    v_sync oid := to_regrole('"conf_zero"');
  BEGIN
  IF v_sync IS NULL THEN
    severity := 'error'; object := v_sync_name; problem := 'the sync role does not exist: the engine can''t read the index'; RETURN NEXT;
  ELSE
    IF pg_has_role(v_sync, v_role, 'MEMBER') OR pg_has_role(v_role, v_sync, 'MEMBER') THEN
      severity := 'error'; object := v_sync_name;
      problem := 'the sync role and the app role are one another''s members: the app would read every row through it'; RETURN NEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles ro WHERE ro.oid = v_sync AND (ro.rolbypassrls OR ro.rolsuper)) THEN
      severity := 'error'; object := v_sync_name;
      problem := format('the sync role lacks BYPASSRLS: the rules apply to the app role, so it reads no row of a table with rules, and an engine''s first snapshot is empty while the changes it decodes hold every row. ALTER ROLE %I BYPASSRLS', v_sync_name); RETURN NEXT;
    END IF;
    FOR r IN SELECT m.tbl, m.col FROM authz_int.masked_columns m
             WHERE has_column_privilege(v_sync, m.tbl, m.col, 'SELECT') LOOP
      severity := 'error'; object := r.tbl || '.' || r.col;
      problem := format('is masked, and the sync role may read it: every client of the engine would. REVOKE SELECT (%I) ON %s FROM %I', r.col, r.tbl, v_sync_name); RETURN NEXT;
    END LOOP;
    FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
             WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"', '"app"."teams"', '"app"."users"']::text[]) x) AND pg_has_role(v_sync, c.relowner, 'MEMBER') LOOP
      severity := 'error'; object := r.tbl::text;
      problem := 'is owned by the sync role (or a role it belongs to): an owner may turn row-level security off and change the rules. The engine connects as a role that owns nothing'; RETURN NEXT;
    END LOOP;
  END IF;
  END;
  FOR r IN SELECT p.pubname, m.tbl, m.col, c.relreplident = 'f' AS whole FROM authz_int.masked_columns m
           JOIN pg_class c ON c.oid = to_regclass(m.tbl) JOIN pg_namespace n ON n.oid = c.relnamespace
           JOIN pg_publication_tables p ON p.schemaname = n.nspname AND p.tablename = c.relname AND m.col = ANY (p.attnames) LOOP
    severity := 'error'; object := r.tbl || '.' || r.col;
    -- (a column list that leaves out a column of the replica identity makes Postgres refuse the table's updates)
    problem := format('is masked, and the publication %s publishes it: an engine that reads the publication reads it. %s', r.pubname,
      CASE WHEN r.whole THEN 'The table''s replica identity is FULL (Electric asks for it), so a column list must hold every column: keep the column in a table of its own, which isn''t published'
           ELSE 'Give the publication a column list without it' END); RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"', '"app"."teams"', '"app"."users"']::text[]) x) LOOP
    -- (FORCE ROW LEVEL SECURITY is no way out: an owner may turn it off again, and row-level security with it)
    IF pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('is owned by %s (or a role it belongs to): an owner skips row-level security, and may turn it off, FORCE ROW LEVEL SECURITY or not. The app role must not own the tables: ALTER TABLE %s OWNER TO the role that applies the policy', 'conf_app', r.tbl);
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'conf_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_table_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'conf_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowstile didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowstile''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'conf_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowstile''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'conf_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"', '"app"."teams"', '"app"."users"', '"app"."folder_teams"', '"app"."team_members"', '"app"."teams"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"', '"app"."teams"', '"app"."users"', '"app"."folder_teams"', '"app"."team_members"', '"app"."teams"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'conf_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules of the table above (apply turns
  -- row-level security on for the ones there are then; later ones are found here), and TRUNCATE skips its
  -- triggers. The tables above: those with rules, and those rowstile watches (a trigger of its own on them)
  FOR r IN WITH RECURSIVE x(tbl, governed) AS (
             SELECT to_regclass(t), true FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) t
             UNION SELECT DISTINCT g.tgrelid::regclass, false FROM pg_trigger g
             JOIN pg_proc f ON f.oid = g.tgfoid AND f.pronamespace = 'authz_int'::regnamespace
             WHERE NOT g.tgisinternal AND g.tgrelid NOT IN (SELECT to_regclass(t) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) t
                                                           WHERE to_regclass(t) IS NOT NULL)
               AND NOT EXISTS (SELECT 1 FROM pg_description c WHERE c.objoid = g.oid AND c.classoid = 'pg_trigger'::regclass
                               AND c.description = 'rowstile: the trigger of the table above, for the rows stored here')),
           d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i JOIN x ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security and %s''s triggers: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'conf_app', r.tbl, r.part, 'conf_app');
      RETURN NEXT;
    END IF;
    -- (on a table without rules, statements on it run the triggers of the table above as their own: the next loop
    -- finds one made since that lacks them)
    IF r.governed AND NOT r.relrowsecurity AND (has_table_privilege(v_role, r.part, 'INSERT') OR has_table_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE') OR has_table_privilege(v_role, r.part, 'SELECT')) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'conf_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- partitions and tables that inherit, made since the last apply: Postgres runs a table's row triggers for its
  -- own rows and its partitions' only, and its statement triggers for statements on it only; applying gives
  -- them to each table under it (whatever the app role may do there: the owner's statements count too, and
  -- rows written through the table above need no privilege of their own)
  FOR r IN SELECT c.child, k.relispartition AS part, (SELECT i.inhparent::regclass FROM pg_inherits i WHERE i.inhrelid = c.child LIMIT 1) AS above,
                  string_agg(c.name::text, ', ' ORDER BY c.name) AS names
           FROM authz_int.child_triggers() c JOIN pg_class k ON k.oid = c.child GROUP BY c.child, k.relispartition LOOP
    severity := 'error'; object := r.child::text;
    IF r.part THEN
      problem := format('is a partition of %s, and was made since the policy was last applied: Postgres runs a table''s statement triggers for statements on it only, so a statement on this partition doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    ELSE
      problem := format('inherits from %s, and was made since the policy was last applied: Postgres runs a table''s row triggers for its own rows only, and its statement triggers for statements on it only, so a rule on a column is not checked on the rows stored here, their shares stay when their key changes, and a statement on this table doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    END IF;
    RETURN NEXT;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x)
             AND has_table_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a key column it may insert or update, not GENERATED ALWAYS; not one the
  -- index only INCLUDEs, which it holds but is not keyed by): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY ((i.indkey::int2[])[0:i.indnkeyatts - 1]) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'conf_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'conf_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.readers, v.typed
           FROM (VALUES ('"app"."folder_teams"', 'folder.team', false), ('"app"."team_members"', 'team.member', false), ('"app"."teams"', 'team.member', true)) v(tbl, readers, typed) LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
    IF (has_table_privilege(v_role, r.tbl, 'INSERT') OR has_table_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'conf_app');
      RETURN NEXT;
    END IF;
    -- ... or read in full: who is linked to what (a type's table without rules is named above)
    IF NOT r.typed AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl)
       AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row, and the policy reads it for %s: who is linked to what is readable. Fine where that is no secret, otherwise give it a type and rules', 'conf_app', r.readers);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES ('"app"."folders"', 'owner_id', 'folder.owner', 'relation folder.owner owner_id', 'nobody'), ('"app"."files"', 'folder_id', 'file.folder', 'relation file.folder folder_id', 'nobody')) v(tbl, col, what, loc, ask)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : %s"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.ask);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- rules for a command the app role has no privilege for (one column's is enough for a read, an insert or
  -- an update: the app may write some columns only)
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.cmd FROM (VALUES ('"app"."files"', 'insert'), ('"app"."files"', 'select'), ('"app"."files"', 'update'), ('"app"."folders"', 'select'), ('"app"."folders"', 'update'), ('"app"."notes"', 'select')) v(tbl, cmd)
           WHERE v.tbl IS NOT NULL LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF r.cmd = 'delete' THEN
      CONTINUE WHEN has_table_privilege(v_role, r.tbl, 'DELETE');
    ELSE
      CONTINUE WHEN has_any_column_privilege(v_role, r.tbl, r.cmd);
    END IF;
    severity := 'warning'; object := r.tbl::text;
    problem := format('the policy has a rule for %s, but %s has no %s privilege on the table: the rule never applies, and the statement fails with Postgres''s own "permission denied for table". GRANT %s ON %s TO %s, or make the rule "%s : nobody"', r.cmd, 'conf_app', upper(r.cmd), upper(r.cmd), r.tbl, 'conf_app', r.cmd);
    RETURN NEXT;
  END LOOP;
  -- relations named like a type that signs in
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text)) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), which signs in: alone in a rule it reads like any %s, and it is this row''s. A name that says what the relation is (author, owner) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.rel);
    RETURN NEXT;
  END LOOP;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    -- (a composite key's columns are 'org_id, parent_id': any of them it may update)
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attnum > 0 AND NOT a.attisdropped
               AND a.attname::text = ANY (string_to_array(r.col, ', ')) AND has_column_privilege(v_role, r.tbl, a.attnum, 'UPDATE')) THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"', '"app"."teams"', '"app"."users"', '"app"."folder_teams"', '"app"."team_members"', '"app"."teams"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') NOT IN ('rowstile masked view')
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_table_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'conf_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['app.files', 'app.folders', 'app.notes', 'app.teams', 'app.users', 'app.folder_teams', 'app.team_members', 'app.teams']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"app"."users"', 'id', 'user: find one by its key, for checks and write rules', NULL), ('"app"."team_members"', 'team_id', 'team.member: find the members of an object', NULL), ('"app"."team_members"', 'user_id', 'team.member: find what a subject is in', NULL), ('"app"."teams"', 'parent_id', 'team.member: find the members of an object', NULL), ('"app"."teams"', 'id', 'team.member: find what a subject is in; team: find one by its key, for checks and write rules', NULL), ('"app"."folders"', 'parent_id', 'folder.parent: find objects by parent_id', NULL), ('"app"."folders"', 'owner_id', 'folder.owner: find objects by owner_id', NULL), ('"app"."folder_teams"', 'folder_id', 'folder.team: find the members of an object', NULL), ('"app"."folder_teams"', 'team_id', 'folder.team: find what a subject is in', NULL), ('"app"."folders"', 'id', 'folder: find one by its key, for checks and write rules', NULL), ('"app"."files"', 'folder_id', 'file.folder: find objects by folder_id', NULL), ('"app"."files"', 'owner_id', 'file.owner: find objects by owner_id', NULL), ('"app"."files"', 'id', 'file: find one by its key, for checks and write rules', NULL), ('"app"."notes"', 'file_id', 'note.file: find objects by file_id', NULL), ('"app"."notes"', 'author_id', 'note.author: find objects by author_id', NULL), ('"app"."notes"', 'id', 'note: find one by its key, for checks and write rules', NULL)) v(tbl, col, why, alone) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order), or what serves a (type, id)
    -- pair alone (its ids where they are two columns, its type where its id is one): a finished one, with no
    -- condition (the lookups are joins, which a partial index doesn't serve), as rowstile indexes counts them; its key
    -- columns only (an index on (a) INCLUDE (b) is not sorted by b)
    IF NOT EXISTS (SELECT 1 FROM pg_index i, unnest(ARRAY[r.col, r.alone]) w(cs)
                   WHERE w.cs IS NOT NULL AND i.indrelid = to_regclass(r.tbl) AND i.indisvalid AND i.indpred IS NULL
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:least(cardinality(string_to_array(w.cs, ', ')), i.indnkeyatts) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(w.cs, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

-- What is wrong with this connection, for the app to check when it starts: SELECT * FROM authz.connection_check()
-- 'error': the rules don't apply to the role this connection runs as. No rows: all is well.
CREATE OR REPLACE FUNCTION authz.connection_check() RETURNS TABLE (severity text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me oid := (SELECT oid FROM pg_roles WHERE rolname = authz_int.caller_role()); v_app oid := to_regrole('"conf_app"'); r record;
BEGIN
  IF (SELECT rolsuper FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s is a superuser: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT; RETURN;
  END IF;
  IF (SELECT rolbypassrls FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s has BYPASSRLS: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT;
  END IF;
  -- the policy's owner (or a member of it): who is signed in is believed without a signature
  IF pg_has_role(v_me, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    severity := 'error';
    problem := format('%s is the policy''s owner, or a member of it: who is signed in is believed without a signature, and it may turn row-level security off. Log in as an app role of its own', v_me::regrole);
    RETURN NEXT;
  END IF;
  -- a table's owner (or a role with its rights) skips row-level security, and may turn it off: FORCE or not
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x)
             AND pg_has_role(v_me, c.relowner, 'USAGE') LOOP
    severity := 'error';
    problem := format('%s owns %s (or has its owner''s rights): an owner skips row-level security, and may turn it off', v_me::regrole, r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a table with rules whose row-level security is off: the rules don't apply
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x) AND NOT c.relrowsecurity LOOP
    severity := 'error';
    problem := format('row-level security is off on %s: the policy''s rules don''t apply to it', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a login that switched to the app role (SET ROLE) but is an administrator: RESET ROLE leaves row-level
  -- security, and its sessions are believed without a signature
  FOR r IN SELECT l.oid::regrole AS login FROM pg_roles l, pg_namespace n
           WHERE l.rolname = session_user AND n.nspname = 'authz_int' AND l.oid <> v_me
             AND (l.rolsuper OR l.rolbypassrls OR pg_has_role(l.oid, n.nspowner, 'MEMBER')) LOOP
    severity := 'error';
    problem := format('this connection logs in as %s, a superuser, BYPASSRLS or the policy''s owner, and switched to %s: RESET ROLE leaves row-level security, and who is signed in is believed without a signature. Log in as the app role', r.login, v_me::regrole);
    RETURN NEXT;
  END LOOP;
  IF v_app IS NULL OR NOT pg_has_role(v_me, v_app, 'USAGE') THEN
    severity := 'error';
    problem := format('%s is not the policy''s app role %s, nor a member of it: the rules apply to %s only',
                      v_me::regrole, 'conf_app', 'conf_app');
    RETURN NEXT;
  END IF;
END $f$;

-- Admin check: every inheritance table matches a from-scratch rebuild
CREATE OR REPLACE FUNCTION authz.verify() RETURNS boolean LANGUAGE sql STABLE AS
  $$ SELECT authz_int."folder__parent__tree_verify"() $$;

-- these functions call each other; their bodies are checked when first used
SET LOCAL check_function_bodies = off;
-- folder.edit (line 22): owner or parent.edit, inherited: who holds it, as keys
CREATE FUNCTION authz_int."sync:folder.edit"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT DISTINCT r.id, r.key, r.d FROM (
  WITH o AS (SELECT DISTINCT x.id FROM unnest(p_ids) x(id)),
  anc AS MATERIALIZED (SELECT c.descendant AS id, c.ancestor AS a FROM authz_int."folder__parent__tree" c WHERE c.descendant IN (SELECT id FROM o)),
  b AS MATERIALIZED (SELECT w.id, w.key, w.d FROM (WITH l3 AS (SELECT r."id" AS id, r."owner_id" AS u FROM "app"."folders" r WHERE r."id" IN (SELECT DISTINCT a.a AS id FROM anc a) AND r."owner_id" IS NOT NULL)
  SELECT l3.id, 'user:' || (l3.u)::text AS key, false AS d FROM l3) w)
  SELECT a.id, b.key, b.d FROM anc a JOIN b ON b.id = a.a) r
$f$;
-- folder.view (line 23): edit or team or viewer or parent.view, inherited: who holds it, as keys
CREATE FUNCTION authz_int."sync:folder.view"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT DISTINCT r.id, r.key, r.d FROM (
  WITH o AS (SELECT DISTINCT x.id FROM unnest(p_ids) x(id)),
  anc AS MATERIALIZED (SELECT c.descendant AS id, c.ancestor AS a FROM authz_int."folder__parent__tree" c WHERE c.descendant IN (SELECT id FROM o)),
  b AS MATERIALIZED ((SELECT w.id, w.key, w.d FROM (WITH l5 AS (SELECT r."id" AS id, r."owner_id" AS u FROM "app"."folders" r WHERE r."id" IN (SELECT DISTINCT a.a AS id FROM anc a) AND r."owner_id" IS NOT NULL)
  SELECT l5.id, 'user:' || (l5.u)::text AS key, false AS d FROM l5) w)
  UNION ALL
  (SELECT w.id, w.key, w.d FROM (WITH l6 AS MATERIALIZED (SELECT s."folder_id" AS id, s."team_id" AS u FROM "app"."folder_teams" s WHERE s."folder_id" IN (SELECT DISTINCT a.a AS id FROM anc a) AND s."team_id" IS NOT NULL)
  SELECT l6.id, 'team#member:' || (l6.u)::text AS key, false AS d FROM l6) w)
  UNION ALL
  (SELECT g.object_id::integer AS id, 'user:' || g.subject_id AS key, false AS d FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id IN (SELECT x.id::text FROM (SELECT DISTINCT a.a AS id FROM anc a) x) AND g.relation = 'viewer' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*'))
  SELECT a.id, b.key, b.d FROM anc a JOIN b ON b.id = a.a) r
$f$;
-- file.view (line 31): edit or viewer or (folder.view and not {confidential}): who holds it, as keys
CREATE FUNCTION authz_int."sync:file.view"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT DISTINCT r.id, r.key, r.d FROM (
  WITH o AS (SELECT DISTINCT x.id FROM unnest(p_ids) x(id))
  (SELECT w.id, w.key, w.d FROM (WITH l1 AS (SELECT r."id" AS id, r."owner_id" AS u FROM "app"."files" r WHERE r."id" IN (SELECT id FROM o) AND r."owner_id" IS NOT NULL)
  SELECT l1.id, 'user:' || (l1.u)::text AS key, false AS d FROM l1) w)
  UNION ALL
  (SELECT w.id, w.key, w.d FROM (WITH l2 AS MATERIALIZED (SELECT r."id" AS id, r."folder_id" AS u FROM "app"."files" r WHERE r."id" IN (SELECT id FROM o) AND r."folder_id" IS NOT NULL)
  SELECT l2.id, f.o_key AS key, f.o_dep AS d FROM l2 JOIN authz_int."sync:folder.edit"(ARRAY(SELECT DISTINCT y.u FROM l2 y)) f ON f.o_id = l2.u) w)
  UNION ALL
  (SELECT g.object_id::integer AS id, 'user:' || g.subject_id AS key, false AS d FROM authz.shares g WHERE g.object_type = 'file' AND g.object_id IN (SELECT x.id::text FROM (SELECT id FROM o) x) AND g.relation = 'viewer' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*')
  UNION ALL
  (SELECT w.id, w.key, w.d FROM (WITH l4 AS MATERIALIZED (SELECT r."id" AS id, r."folder_id" AS u FROM "app"."files" r WHERE r."id" IN (SELECT r."id" AS id FROM "app"."files" r WHERE r."id" IN (SELECT id FROM o) AND NOT coalesce((confidential), false)) AND r."folder_id" IS NOT NULL)
  SELECT l4.id, f.o_key AS key, f.o_dep AS d FROM l4 JOIN authz_int."sync:folder.view"(ARRAY(SELECT DISTINCT y.u FROM l4 y)) f ON f.o_id = l4.u) w)) r
$f$;
-- app.files: the keys that may read each row (line 55)
CREATE FUNCTION authz_int."sync:file"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH o AS (SELECT x."id" AS id FROM "app"."files" x WHERE x."id" IN (SELECT unnest(p_ids) AS id))
  SELECT DISTINCT r.id, r.key, r.d FROM (
  SELECT f.o_id AS id, f.o_key AS key, f.o_dep AS d FROM authz_int."sync:file.view"(ARRAY(SELECT x.id FROM (SELECT id FROM o) x)) f) r
$f$;
-- app.folders: the keys that may read each row (line 56)
CREATE FUNCTION authz_int."sync:folder"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH o AS (SELECT x."id" AS id FROM "app"."folders" x WHERE x."id" IN (SELECT unnest(p_ids) AS id))
  SELECT DISTINCT r.id, r.key, r.d FROM (
  SELECT f.o_id AS id, f.o_key AS key, f.o_dep AS d FROM authz_int."sync:folder.view"(ARRAY(SELECT x.id FROM (SELECT id FROM o) x)) f) r
$f$;
-- note.view (line 38): file.view: who holds it, as keys
CREATE FUNCTION authz_int."sync:note.view"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT DISTINCT r.id, r.key, r.d FROM (
  WITH o AS (SELECT DISTINCT x.id FROM unnest(p_ids) x(id))
  SELECT w.id, w.key, w.d FROM (WITH l7 AS MATERIALIZED (SELECT r."id" AS id, r."file_id" AS u FROM "app"."notes" r WHERE r."id" IN (SELECT id FROM o) AND r."file_id" IS NOT NULL)
  SELECT l7.id, f.o_key AS key, f.o_dep AS d FROM l7 JOIN authz_int."sync:file.view"(ARRAY(SELECT DISTINCT y.u FROM l7 y)) f ON f.o_id = l7.u) w) r
$f$;
-- app.notes: the keys that may read each row (line 57)
CREATE FUNCTION authz_int."sync:note"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH o AS (SELECT x."id" AS id FROM "app"."notes" x WHERE x."id" IN (SELECT unnest(p_ids) AS id))
  SELECT DISTINCT r.id, r.key, r.d FROM (
  SELECT f.o_id AS id, f.o_key AS key, f.o_dep AS d FROM authz_int."sync:note.view"(ARRAY(SELECT x.id FROM (SELECT id FROM o) x)) f) r
$f$;
-- team.member (line 13): who holds it, as keys
CREATE FUNCTION authz_int."sync:team.member"(p_ids integer[]) RETURNS TABLE (o_id integer, o_key text, o_dep boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT DISTINCT r.id, r.key, r.d FROM (
  WITH o AS (SELECT DISTINCT x.id FROM unnest(p_ids) x(id))
  (SELECT w.id, w.key, w.d FROM (WITH l8 AS (SELECT s."team_id" AS id, s."user_id" AS u FROM "app"."team_members" s WHERE s."team_id" IN (SELECT id FROM o) AND s."user_id" IS NOT NULL)
  SELECT l8.id, 'user:' || (l8.u)::text AS key, false AS d FROM l8) w)
  UNION ALL
  (SELECT w.id, w.key, w.d FROM (WITH l9 AS MATERIALIZED (SELECT s."parent_id" AS id, s."id" AS u FROM "app"."teams" s WHERE s."parent_id" IN (SELECT id FROM o) AND s."id" IS NOT NULL)
  SELECT l9.id, 'team#member:' || (l9.u)::text AS key, false AS d FROM l9) w)) r
$f$;
-- the keys the principals of user hold
CREATE FUNCTION authz_int."sync_keys:user"(p_ids text[]) RETURNS TABLE (o_id text, o_key text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE k(id, key) AS (
    SELECT x."id"::text, v.key FROM "app"."users" x
      CROSS JOIN LATERAL (VALUES ('user:' || x."id"::text), ('user:*'), ('anyone')) v(key)
    WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(p_ids) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))))
    UNION
    SELECT k.id, g.grp FROM k JOIN authz_sync.groups g ON g.key = k.key)
  SELECT k.id, k.key FROM k
$f$;
-- what reads the objects a transaction changed, and what reads those, to the end (no limit: each is worked out again)
CREATE FUNCTION authz_int.sync_spread(p_tx bigint, p_round int) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE r int := p_round; n bigint;
BEGIN
  LOOP
    INSERT INTO authz_int.sync_todo (txid, type, id, round)
    SELECT p_tx, d.t, d.i, r + 1 FROM (
      SELECT 'file'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "app"."files" x WHERE x."folder_id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.type = 'folder' AND x.round = r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))))) v(id)
      UNION ALL SELECT 'file'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.type = 'folder' AND x.round = r AND x.id = '*')
      UNION ALL SELECT 'folder'::text AS t, v.id::text AS i FROM (SELECT c.descendant::text FROM authz_int."folder__parent__tree" c WHERE c.ancestor IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.type = 'folder' AND x.round = r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))))) v(id)
      UNION ALL SELECT 'folder'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.type = 'folder' AND x.round = r AND x.id = '*')
      UNION ALL SELECT 'note'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "app"."notes" x WHERE x."file_id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.type = 'file' AND x.round = r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))))) v(id)
      UNION ALL SELECT 'note'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.type = 'file' AND x.round = r AND x.id = '*')) d WHERE d.i IS NOT NULL
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0 AND NOT EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.round > r);
    r := r + 1;
  END LOOP;
  RETURN r;
END $f$;
-- The index made current for the objects a transaction changed and what reads them (the difference written, not
-- every row again): at its commit, in it, or after it, by the worker. The groups first, then the keys (a principal
-- holds the keys of every group whose members hold one of its own, through groups inside groups), then the readers
-- (JIT off: its statements read a few rows each, through indexes, which a plan made for many would compile for; no
-- merge joins: its sets of keys, which the planner can't count, are joined by hash, not sorted as text)
CREATE FUNCTION authz_int.sync_process() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET jit = off SET enable_mergejoin = off AS $f$
DECLARE
  v_tx bigint := txid_current();
  v_round int;
  v_mode int[]; v_w int[]; v_r int[]; v_s int; v_x boolean;
  v_ids text[]; v_part text[]; v_from int; v_now text[];
  v_keys text[] := '{}';     -- the keys a principal gained or lost
  v_came text[] := '{}';     -- the principals who are somebody now, and held no key (type:id)
  v_whole text[] := '{}';    -- the principal types worked out whole
  v_keys_locked boolean := false;
  v_all boolean;               -- every principal's keys worked out whole (applying): the groups' changes aren't followed
  v_n bigint;
  v_found int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx) THEN RETURN; END IF;
  IF current_setting('transaction_isolation') IN ('repeatable read', 'serializable') THEN
    -- a snapshot older than another's index write: a serialization error, rather than readers worked out from
    -- what it can't see
    PERFORM 1 FROM authz_int.sync_stripes s ORDER BY s.stripe FOR UPDATE;
    UPDATE authz_int.sync_stripes SET n = n;
    v_round := authz_int.sync_spread(v_tx, 0);
  ELSE
    -- READ COMMITTED: the lock rows of what the work writes (what changed, and what reads it), and, shared, of what
    -- it reads (the folders above, what they link to), in one order. A writer whose work meets this one's waits for
    -- it, then sees what it committed; once they are held, what reads the changes is looked for again, and the lock
    -- rows of anything new are taken too, until there is none
    v_mode := array_fill(0, ARRAY[4096]);
    LOOP
      v_round := authz_int.sync_spread(v_tx, 0);
      IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*') THEN
        v_w := ARRAY(SELECT generate_series(0, 4095));
        v_r := '{}';
      ELSE
        v_w := ARRAY(SELECT DISTINCT pg_catalog.hashtext(x.type || ':' || x.id) & 4095
                     FROM authz_int.sync_todo x WHERE x.txid = v_tx);
        v_r := ARRAY(SELECT DISTINCT pg_catalog.hashtext(d.k) & 4095 FROM (
                        SELECT 'folder:' || v.id FROM (SELECT (x."folder_id")::text FROM "app"."files" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'file' AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)) v(id)
                        UNION SELECT 'folder:' || v.id FROM (SELECT c.ancestor::text FROM authz_int."folder__parent__tree" c WHERE c.descendant IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'folder' AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))))) v(id)
                        UNION SELECT 'file:' || v.id FROM (SELECT (x."file_id")::text FROM "app"."notes" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'note' AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)) v(id)) d(k) WHERE d.k IS NOT NULL);
      END IF;
      v_n := 0;
      FOR v_s, v_x IN SELECT z.s, bool_or(z.x) FROM (SELECT unnest(v_w) AS s, true AS x UNION ALL SELECT unnest(v_r), false) z
                      GROUP BY z.s ORDER BY z.s LOOP
        CONTINUE WHEN v_mode[v_s + 1] = 2 OR (NOT v_x AND v_mode[v_s + 1] = 1);
        IF v_x THEN
          UPDATE authz_int.sync_stripes SET n = n WHERE stripe = v_s;
          v_mode[v_s + 1] := 2;
        ELSE
          PERFORM 1 FROM authz_int.sync_stripes WHERE stripe = v_s FOR SHARE;
          v_mode[v_s + 1] := 1;
        END IF;
        v_n := v_n + 1;
      END LOOP;
      EXIT WHEN v_n = 0;
    END LOOP;
  END IF;
  v_all := (SELECT count(DISTINCT x.type) FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*'
            AND x.type = ANY (ARRAY['user']::text[])) = 1;
  -- team's groups
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'team' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."teams" x UNION SELECT x."team_id"::text FROM "app"."team_members" x UNION SELECT x."parent_id"::text FROM "app"."teams" x UNION SELECT g.object_id FROM authz.shares g WHERE g.object_type = 'team' UNION SELECT substr(g.grp, strpos(g.grp, ':') + 1) FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) = ANY (ARRAY['team#member:']::text[])) ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'team') END;
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
      WITH fresh AS MATERIALIZED (SELECT 'team#member:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.member"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f WHERE NOT f.o_dep),
      gone AS (DELETE FROM authz_sync.groups g WHERE g.grp IN (SELECT 'team#member:' || v FROM unnest(v_part) v)
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.grp = g.grp AND f.key = g.key) RETURNING g.grp, g.key),
      made AS (INSERT INTO authz_sync.groups SELECT f.grp, f.key FROM fresh f ON CONFLICT DO NOTHING RETURNING grp, key)
      INSERT INTO authz_int.sync_moved SELECT v_tx, z.grp, z.key, z.made
      FROM (SELECT grp, key, false AS made FROM gone UNION ALL SELECT grp, key, true FROM made) z
      WHERE NOT v_all;
  END LOOP;
  -- the keys, where the groups' rows or the principals changed: under one lock row, taken last (nothing after it waits
  -- for another lock)
  IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx)
     OR EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = ANY (ARRAY['user']::text[])) THEN
    IF NOT v_keys_locked THEN
      UPDATE authz_int.locks SET n = n + 1 WHERE type = 'sync#keys';
    END IF;
    -- the principals of user: every one worked out whole (applying), or those that changed: one who is
    -- nobody now (gone, or failing the type's where) holds no key, and one who is somebody now and held none gets theirs
    IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user' AND x.id = '*') THEN
      v_whole := v_whole || 'user'::text;
      v_ids := ARRAY(SELECT x."id"::text FROM "app"."users" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'user');
      WITH fresh AS MATERIALIZED (SELECT * FROM authz_int."sync_keys:user"(v_ids)),
      gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id IN (SELECT unnest(v_ids))
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_id = k.principal_id AND f.o_key = k.key) RETURNING k.key),
      made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM fresh f ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.k), '{}') INTO v_keys FROM (SELECT key FROM gone UNION SELECT key FROM made) z(k);
    ELSE
      v_ids := ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user');
      IF cardinality(v_ids) > 0 THEN
        v_now := ARRAY(SELECT x."id"::text FROM "app"."users" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(v_ids) v WHERE pg_catalog.pg_input_is_valid(v, 'integer')))));
        WITH gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = ANY (v_ids)
                      AND k.principal_id <> ALL (v_now) RETURNING k.key)
        SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
        v_came := v_came || ARRAY(SELECT 'user' || ':' || v FROM unnest(v_now) v WHERE NOT EXISTS (
          SELECT 1 FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = v));
      END IF;
    END IF;
    -- a group's row gone: the keys above it that its member's holders held may go, unless what is left gives them
    -- again (each found given is taken back from those that may go, as often as it finds more)
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c)
      -- (the holders of each key, a lookup by the keys' index: OFFSET 0 keeps the planner from reading every key for a
      -- few; then the sets joined whole)
      , by_src AS MATERIALIZED (
        SELECT DISTINCT up.c, k.principal_type AS pt, k.principal_id AS pid FROM up
        CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                            AND k.principal_type <> ALL (v_whole) OFFSET 0) k),
      by_c AS MATERIALIZED (
        SELECT c.c, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT up.c FROM up) c
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = c.c OFFSET 0) h)
      INSERT INTO authz_int.sync_lost (txid, ptype, pid, key)
      SELECT v_tx, s.pt, s.pid, s.c FROM by_src s JOIN by_c h ON h.c = s.c AND h.pt = s.pt AND h.pid = s.pid
      ON CONFLICT DO NOTHING;
      -- given again: by a member it holds that may not go (the holders of the members of the groups that may go, once
      -- each); then, round by round, by a member just found given
      WITH members AS MATERIALIZED (
        SELECT g.grp, g.key FROM (SELECT DISTINCT l.key FROM authz_int.sync_lost l WHERE l.txid = v_tx) c
        CROSS JOIN LATERAL (SELECT g.grp, g.key FROM authz_sync.groups g WHERE g.grp = c.key OFFSET 0) g),
      held AS MATERIALIZED (
        SELECT m.key, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT key FROM members) m
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = m.key OFFSET 0) h),
      -- (the groups each holder holds a member of, that may not go; then the candidates they give again)
      supported AS MATERIALIZED (
        SELECT DISTINCT g.grp, h.pt, h.pid FROM members g JOIN held h ON h.key = g.key
        WHERE NOT EXISTS (SELECT 1 FROM authz_int.sync_lost o WHERE o.txid = v_tx AND o.ptype = h.pt AND o.pid = h.pid
                          AND o.key = h.key)),
      given AS (SELECT l.ptype, l.pid, l.key FROM authz_int.sync_lost l
                JOIN supported s ON s.grp = l.key AND s.pt = l.ptype AND s.pid = l.pid WHERE l.txid = v_tx),
      r AS (DELETE FROM authz_int.sync_lost l USING given z WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid
            AND l.key = z.key RETURNING l.ptype, l.pid, l.key)
      INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, 1 FROM r;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_found := 1;
      WHILE v_n > 0 LOOP
        WITH r AS (DELETE FROM authz_int.sync_lost l
                   USING (SELECT DISTINCT f.ptype, f.pid, g.grp FROM authz_int.sync_found f
                          JOIN authz_sync.groups g ON g.key = f.key WHERE f.txid = v_tx AND f.round = v_found) z
                   WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid AND l.key = z.grp
                   RETURNING l.ptype, l.pid, l.key)
        INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, v_found + 1 FROM r;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        v_found := v_found + 1;
      END LOOP;
      DELETE FROM authz_int.sync_found f WHERE f.txid = v_tx;
      WITH gone AS (DELETE FROM authz_sync.keys k USING authz_int.sync_lost l WHERE l.txid = v_tx
                    AND k.principal_type = l.ptype AND k.principal_id = l.pid AND k.key = l.key RETURNING k.key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
      DELETE FROM authz_int.sync_lost l WHERE l.txid = v_tx;
    END IF;
    -- a group's row made: its member's holders hold the group, and the groups above it
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c),
      made AS (INSERT INTO authz_sync.keys SELECT DISTINCT k.principal_type, k.principal_id, up.c FROM up
               CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                                   AND k.principal_type <> ALL (v_whole) OFFSET 0) k
               ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
    DELETE FROM authz_int.sync_moved m WHERE m.txid = v_tx;
    -- the principals who are somebody now: their keys, worked out whole
    IF cardinality(v_came) > 0 THEN
    WITH made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM authz_int."sync_keys:user"(ARRAY(
                    SELECT substr(c, 6) FROM unnest(v_came) c WHERE left(c, 5) = 'user:')) f
                  ON CONFLICT DO NOTHING RETURNING key)
    SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
  END IF;
  -- file's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'file' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."files" x UNION SELECT x."id"::text FROM authz_sync."file__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'file') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'file') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:file"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."file__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."file__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."file__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'file' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'file', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- folder's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'folder' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."folders" x UNION SELECT x."id"::text FROM authz_sync."folder__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'folder') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'folder') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:folder"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."folder__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."folder__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."folder__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'folder' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'folder', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- note's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'note' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."notes" x UNION SELECT x."id"::text FROM authz_sync."note__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'note') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'note') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:note"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."note__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."note__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."note__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'note' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'note', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  DELETE FROM authz_int.sync_todo x WHERE x.txid = v_tx;
END $f$;
-- the index worked out again where what it is worked out by changed (p_hash), or all of it (p_force); by difference
CREATE FUNCTION authz_int.sync_refresh(p_hash text, p_force boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF p_force OR NOT EXISTS (SELECT 1 FROM authz_sync.definitions d WHERE d.name = 'index' AND d.hash = p_hash) THEN
    -- what this policy no longer keeps
  DELETE FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) <> ALL (ARRAY['team#member:']::text[]);
    DELETE FROM authz_sync.keys k WHERE k.principal_type <> ALL (ARRAY['user']::text[]);
    DELETE FROM authz_sync.expanded x WHERE x.object_type <> ALL (ARRAY['file', 'folder', 'note']::text[]);
    INSERT INTO authz_int.sync_todo (txid, type, id) SELECT txid_current(), x, '*' FROM unnest(ARRAY['file', 'folder', 'note', 'team', 'user']::text[]) x ON CONFLICT DO NOTHING;
  END IF;
  PERFORM authz_int.sync_process();
  IF p_hash IS NOT NULL THEN
    INSERT INTO authz_sync.definitions VALUES ('index', p_hash) ON CONFLICT (name) DO UPDATE SET hash = EXCLUDED.hash;
  END IF;
END $f$;
-- Shares that start or end later change who reads their objects with no write: SELECT authz.sync_tick() works out
-- again the readers of those whose start or end passed since it last ran, and says how many shares. Schedule it
-- (pg_cron, the app's jobs) as often as a share that ends should leave the engines' clients
CREATE OR REPLACE FUNCTION authz.sync_tick() RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_from timestamptz := coalesce((SELECT s.value::timestamptz FROM authz.settings s WHERE s.key = 'sync_tick_to'), '-infinity');
  v_to timestamptz := now();
  n bigint;
BEGIN
  PERFORM authz_int.sync_dirty(g.object_type, array_agg(DISTINCT g.object_id)) FROM authz.shares g
  WHERE (g.expires_at > v_from AND g.expires_at <= v_to) OR (g.starts_at > v_from AND g.starts_at <= v_to)
  GROUP BY g.object_type;
  SELECT count(*) INTO n FROM authz.shares g
  WHERE (g.expires_at > v_from AND g.expires_at <= v_to) OR (g.starts_at > v_from AND g.starts_at <= v_to);
  -- (written in ISO 8601, which every session reads alike whatever its DateStyle)
  INSERT INTO authz.settings VALUES ('sync_tick_to', to_char(v_to AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
    ON CONFLICT (key) DO UPDATE SET value = to_char(greatest(authz.settings.value::timestamptz, v_to) AT TIME ZONE 'UTC',
                                                    'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  RETURN n;
END $f$;
-- Admin check: the sync index matches a rebuild (false says which part differs, in a notice)
CREATE OR REPLACE FUNCTION authz.sync_verify() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT grp, key FROM authz_sync.groups), f AS MATERIALIZED (SELECT 'team#member:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.member"(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x."id"::text FROM "app"."teams" x UNION SELECT x."team_id"::text FROM "app"."team_members" x UNION SELECT x."parent_id"::text FROM "app"."teams" x UNION SELECT g.object_id FROM authz.shares g WHERE g.object_type = 'team' UNION SELECT substr(g.grp, strpos(g.grp, ':') + 1) FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) = ANY (ARRAY['team#member:']::text[]))) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f WHERE NOT f.o_dep)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'groups';
    RETURN false;
  END IF;
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT principal_type, principal_id, key FROM authz_sync.keys), f AS MATERIALIZED (SELECT 'user'::text, f.o_id, f.o_key FROM authz_int."sync_keys:user"(ARRAY(SELECT x."id"::text FROM "app"."users" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'user')) f)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'keys';
    RETURN false;
  END IF;
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT x."id"::text, x.key, false FROM authz_sync."file__readers" x UNION ALL SELECT x.object_id, x.key, true FROM authz_sync.expanded x WHERE x.object_type = 'file'), f AS MATERIALIZED (SELECT f.o_id::text, f.o_key, f.o_dep FROM (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:file"(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x."id"::text FROM "app"."files" x UNION SELECT x."id"::text FROM authz_sync."file__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'file')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f) f)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'file''s readers, and what they were worked out from';
    RETURN false;
  END IF;
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT x."id"::text, x.key, false FROM authz_sync."folder__readers" x UNION ALL SELECT x.object_id, x.key, true FROM authz_sync.expanded x WHERE x.object_type = 'folder'), f AS MATERIALIZED (SELECT f.o_id::text, f.o_key, f.o_dep FROM (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:folder"(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x."id"::text FROM "app"."folders" x UNION SELECT x."id"::text FROM authz_sync."folder__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'folder')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f) f)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'folder''s readers, and what they were worked out from';
    RETURN false;
  END IF;
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT x."id"::text, x.key, false FROM authz_sync."note__readers" x UNION ALL SELECT x.object_id, x.key, true FROM authz_sync.expanded x WHERE x.object_type = 'note'), f AS MATERIALIZED (SELECT f.o_id::text, f.o_key, f.o_dep FROM (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:note"(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x."id"::text FROM "app"."notes" x UNION SELECT x."id"::text FROM authz_sync."note__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'note')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f) f)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'note''s readers, and what they were worked out from';
    RETURN false;
  END IF;
  RETURN true;
END $f$;
-- In the same transaction (the default), nothing waits: authz.sync_work() has nothing to do (0), and
-- authz.sync_behind() says the index holds every change committed (NULL). They are for sync after commit
CREATE OR REPLACE FUNCTION authz.sync_work() RETURNS bigint
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$ SELECT 0::bigint $f$;
CREATE OR REPLACE FUNCTION authz.sync_behind() RETURNS interval
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$ SELECT NULL::interval $f$;
SET LOCAL check_function_bodies = on;

-- where each rule, relation and invariant is written, for messages (Core.line_sql)
CREATE TABLE authz_gen.policy_lines (what text PRIMARY KEY, loc text NOT NULL);
INSERT INTO authz_gen.policy_lines VALUES
  ('relation file.folder folder_id', 'line 26'),
  ('relation folder.owner owner_id', 'line 18'),
  ('rule app.files insert', 'line 47'),
  ('rule app.files update', 'line 48'),
  ('rule app.files update owner_id', 'line 49'),
  ('rule app.folders update', 'line 42'),
  ('rule app.folders update parent_id after', 'line 43'),
  ('share file.viewer user', 'line 28'),
  ('share folder.viewer user', 'line 20');

DO $k$
DECLARE v_old text;
BEGIN
  SELECT string_agg(p.oid::regprocedure || ' (' || (
           SELECT string_agg(DISTINCT pg_catalog.pg_describe_object(d.classid, d.objid, 0), ', ')
           FROM pg_depend d WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = p.oid AND d.deptype = 'n') || ')', '; ')
  INTO v_old FROM pg_proc p
  WHERE p.oid || ' ' || p.ctid = ANY (string_to_array(current_setting('authz_ctx.kept_functions', true), ';'));
  PERFORM set_config('authz_ctx.kept_functions', '', true);
  IF v_old IS NOT NULL THEN
    RAISE EXCEPTION 'this policy no longer makes a function that something in the database uses: % [AZ614]', v_old
      USING HINT = 'Drop or change what uses it, then apply again.';
  END IF;
END $k$;

DO $kv$
DECLARE v_old text;
BEGIN
  SELECT string_agg(c.oid::regclass || ' (' || (
           SELECT string_agg(DISTINCT pg_catalog.pg_describe_object(d.classid, d.objid, 0), ', ')
           FROM pg_depend d WHERE d.refclassid = 'pg_class'::regclass AND d.refobjid = c.oid AND d.deptype = 'n'
             AND NOT (d.classid = 'pg_rewrite'::regclass AND d.objid IN (SELECT oid FROM pg_rewrite WHERE ev_class = c.oid))) || ')', '; ')
  INTO v_old FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
  WHERE c.relkind = 'v' AND d.description IN ('rowstile masked view') AND c.oid <> ALL (ARRAY[to_regclass('"app"."notes_visible"')::oid]::oid[]);
  IF v_old IS NOT NULL THEN
    RAISE EXCEPTION 'this policy no longer makes a masked view that something in the database is built on: % [AZ617]', v_old
      USING HINT = 'Drop or change what is built on it, then apply again.';
  END IF;
END $kv$;

-- Tables that had rules before but have none now keep row-level security on
DO $l$
DECLARE t record;
BEGIN
  FOR t IN SELECT o.tbl FROM pg_temp.authz_old_tables o JOIN pg_class c ON c.oid = o.tbl
           WHERE c.relrowsecurity AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = o.tbl) LOOP
    RAISE WARNING '% has no rules any more, and row-level security is still on, so the app role sees none of its rows. If that is not what you want: ALTER TABLE % DISABLE ROW LEVEL SECURITY', t.tbl, t.tbl;
  END LOOP;
END $l$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

SELECT authz_int.sync_refresh('dca870aa950b11ce048dd553adaf59cc');
DO $sw$
DECLARE n bigint; m bigint;
BEGIN
  SELECT count(*) FILTER (WHERE g.caveat IS NOT NULL), count(*) FILTER (WHERE g.subject_type = 'link') INTO n, m
  FROM authz.shares g WHERE (g.object_type = 'file' AND g.relation = 'viewer') OR (g.object_type = 'folder' AND g.relation = 'viewer');
  IF n > 0 THEN
    RAISE WARNING '% shares with a caveat give nothing through the sync index: a caveat is checked at each request, with what it says', n;
  END IF;
  IF m > 0 THEN
    RAISE WARNING '% share links give nothing through the sync index: a synced client is a principal, without links', m;
  END IF;
END $sw$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "conf_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."file__view", authz_int."file__viewer", authz_int."folder__edit", authz_int."folder__edit__direct", authz_int."folder__team", authz_int."folder__view", authz_int."folder__viewer" TO "conf_app";

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"conf_zero"'); v_app oid := to_regrole('"conf_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role conf_zero does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE conf_zero LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role conf_zero is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role conf_zero and the app role conf_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role conf_zero may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "conf_zero";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "conf_zero";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."file__view"', 'authz_int."file__viewer"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."folder__team"', 'authz_int."folder__view"', 'authz_int."folder__viewer"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.files:column owner_id:items"', '"app.files:column owner_id:why"', '"app.files:insert:items"', '"app.files:insert:refuse"', '"app.files:insert:why"', '"app.files:rules:explain"', '"app.files:update:items"', '"app.files:update:refuse"', '"app.files:update:why"', '"app.folders:column parent_id after:items"', '"app.folders:column parent_id after:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.notes:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, integer, text)', 'authz.explain(text, integer, text, text)', 'authz.list_shares(text, integer)', 'authz.list_links(text, integer)', 'authz.revoke_link(text, integer, text)', 'authz.create_link(text, integer, text, timestamptz)', 'authz.create_role(text, integer, text, text, text[])', 'authz.roles_of(text, integer)', 'authz.request_access(text, integer, text, text, interval)', 'authz.break_glass(text, integer, text, text, interval)', 'authz.start_review(text, integer, timestamptz)', 'authz.can(text, integer, text)', 'authz.who_among(text, integer, text, text[], text)', 'authz.perms(text, integer)', 'authz.share(text, text, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, integer, text)', 'authz.share(text, integer, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, text, text)', 'authz.share(text, integer, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, integer, text)']::regprocedure[]))
UNION ALL
SELECT n.nspname::text, gw.who, a.privilege_type,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who)
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname = 'authz_sync' AND a.grantee <> n.nspowner
    AND NOT (a.grantee = to_regrole('"conf_zero"') AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON TABLE %s FROM %s CASCADE', a.privilege_type, c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND a.grantee <> c.relowner
    AND NOT (a.grantee = to_regrole('"conf_zero"') AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND att.attacl IS NOT NULL LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

